  { x: 25, z: 2, type: 'H' }, { x: 33, z: 4, type: 'A' }, { x: 14, z: 7, type: 'W' },
  { x: 30, z: 7, type: 'H' }, { x: 3, z: 12, type: 'A' }, { x: 6, z: 15, type: 'W' },
  { x: 29, z: 12, type: 'H' }, { x: 32, z: 15, type: 'A' }, { x: 8, z: 21, type: 'W' },
  { x: 13, z: 24, type: 'H' }, { x: 23, z: 21, type: 'A' }, { x: 28, z: 24, type: 'W' },
  { x: 2, z: 29, type: 'H' }, { x: 34, z: 29, type: 'A' }, { x: 10, z: 32, type: 'W' },
  { x: 26, z: 32, type: 'H' }, { x: 18, z: 34, type: 'A' },
];
// WHY: portas nas passagens entre regiões
const FIXED_DOORS = [
  { x: 8, z: 10 }, { x: 26, z: 10 }, { x: 8, z: 12 }, { x: 27, z: 12 },
  { x: 8, z: 16 }, { x: 27, z: 16 }, { x: 10, z: 30 }, { x: 24, z: 30 },
];
const FIXED_EXITS = [
  { x: 3, z: 41 }, { x: 32, z: 41 },
];
const FIXED_SECRETS = [
  { x: 33, z: 31 },
];
// WHY: tochas ao longo de paredes (iluminação das salas)
const FIXED_TORCHES = [
  { x: 2, z: 3 }, { x: 33, z: 3 }, { x: 2, z: 9 }, { x: 33, z: 9 },
  { x: 2, z: 19 }, { x: 33, z: 19 }, { x: 2, z: 21 }, { x: 33, z: 21 },
  { x: 2, z: 31 }, { x: 33, z: 41 },
];
// WHY: poça de lava na passagem do corredor (rows 19) — pulável
const FIXED_LAVA = [
  { x: 11, z: 19 }, { x: 13, z: 19 }, { x: 15, z: 19 }, { x: 17, z: 19 }, { x: 19, z: 19 },
];

// WHY: garante que uma posição fixa é válida (dentro, não parede, não borda, livre)
const assertCellFree = (grid, x, z, what) => {
  if (x <= 0 || x >= C.MAP.gridW - 1 || z <= 0 || z >= C.MAP.gridH - 1) {
    throw new Error(`${what} (${x},${z}) na borda!`);
  }
  const tile = grid[z][x];
  if (tile !== C.TILES.FLOOR) {
    throw new Error(`${what} (${x},${z}) não está em floor (tile='${tile}')!`);
  }
};

// WHY: constrói o nível completo
const buildLevel = () => {
  let grid = RAW_MAP.map(normalizeRow);
  grid = padGrid(grid);

  // WHY: valida o spawn (salão aberto — lição ciclo 1)
  const spawnX = C.PLAYER.startPos.x;
  const spawnZ = C.PLAYER.startPos.z;
  if (grid[spawnZ][spawnX] !== C.TILES.FLOOR) {
    throw new Error('Spawn não está em floor!');
  }
  const neighbors = [
    grid[spawnZ - 1][spawnX],
    grid[spawnZ + 1][spawnX],
    grid[spawnZ][spawnX - 1],
    grid[spawnZ][spawnX + 1],
  ];
  for (const n of neighbors) {
    if (n === C.TILES.WALL) throw new Error('Spawn cercado por parede!');
  }

  // WHY: aplica itens fixos no grid (validação rígida)
  for (const p of FIXED_PICKUPS) { assertCellFree(grid, p.x, p.z, 'pickup'); grid[p.z][p.x] = p.type; }
  for (const d of FIXED_DOORS) { assertCellFree(grid, d.x, d.z, 'door'); grid[d.z][d.x] = C.TILES.DOOR; }
  for (const e of FIXED_EXITS) { assertCellFree(grid, e.x, e.z, 'exit'); grid[e.z][e.x] = C.TILES.EXIT; }
  for (const s of FIXED_SECRETS) { assertCellFree(grid, s.x, s.z, 'secret'); grid[s.z][s.x] = C.TILES.SECRET; }
  for (const t of FIXED_TORCHES) { assertCellFree(grid, t.x, t.z, 'torch'); grid[t.z][t.x] = C.TILES.TORCH; }
  for (const l of FIXED_LAVA) { assertCellFree(grid, l.x, l.z, 'lava'); grid[l.z][l.x] = C.TILES.LAVA; }

  const pickups = FIXED_PICKUPS.map((p) => ({ ...p }));
  const doors = FIXED_DOORS.map((d) => ({ x: d.x, z: d.z, state: 'closed' }));
  const exits = FIXED_EXITS.map((e) => ({ x: e.x, z: e.z }));
  const secrets = FIXED_SECRETS.map((s) => ({ x: s.x, z: s.z }));
  const torches = FIXED_TORCHES.map((t) => ({ x: t.x, z: t.z }));
  const lava = FIXED_LAVA.map((l) => ({ x: l.x, z: l.z }));

  const playerSpawn = { x: spawnX, z: spawnZ, yaw: Math.PI / 2 };

  return { grid, zones: ZONES, playerSpawn, exits, secrets, torches, pickups, doors, lava };
};

// WHY: verifica se uma célula é parede
const isWall = (grid, x, z) => {
  if (z < 0 || z >= grid.length || x < 0 || x >= grid[0].length) return true;
  return grid[z][x] === C.TILES.WALL;
};

// WHY: verifica se um tile é sólido (parede ou porta fechada)
const isSolidTile = (ch) => {
  return ch === C.TILES.WALL || ch === C.TILES.DOOR;
};

// WHY: retorna o tile em uma posição
const cellAt = (grid, x, z) => {
  if (z < 0 || z >= grid.length || x < 0 || x >= grid[0].length) return C.TILES.WALL;
  return grid[z][x];
};

// WHY: raycasting DDA para verificar linha de visão
const hasLineOfSight = (grid, x0, z0, x1, z1, doors = []) => {
  const dx = x1 - x0;
  const dz = z1 - z0;
  const steps = Math.max(Math.abs(dx), Math.abs(dz));
  if (steps === 0) return true;

  const sx = dx / steps;
  const sz = dz / steps;

  let curX = x0;
  let curZ = z0;
  for (let i = 0; i < steps; i++) {
    const tx = Math.floor(curX + 0.5);
    const tz = Math.floor(curZ + 0.5);
    if (tx < 0 || tx >= grid[0].length || tz < 0 || tz >= grid.length) return false;
    const tile = grid[tz][tx];
    if (tile === C.TILES.WALL) return false;
    const doorIdx = doors.findIndex((d) => d.x === tx && d.z === tz);
    if (doorIdx !== -1 && doors[doorIdx].state === 'closed') return false;
    curX += sx;
    curZ += sz;
  }
  return true;
};

export {
  buildLevel,
  isWall,
  isSolidTile,
  cellAt,
  hasLineOfSight,
  normalizeRow,
  padGrid,
  RAW_MAP,
  ZONES,
};

