// WHY: move e resolve colisão AABB por eixo — checa a área varrida inteira
const moveAxis = (pos, vel, axis, dt, grid, radius) => {
  const newVel = { ...vel };
  const newPos = { ...pos };

  // WHY: eixo complementar (y é o eixo "outro" nos testes 2D)
  const other = axis === 'x' ? 'y' : 'x';
  const oldMain = pos[axis];
  const oldOther = pos[other];
  const newMain = oldMain + vel[axis] * dt;
  const newOther = oldOther + vel[other] * dt;

  // WHY: faixa varrida pelo AABB do centro antigo ao novo (+radius)
  const lo = Math.floor(Math.min(oldMain, newMain) - radius);
  const hi = Math.floor(Math.max(oldMain, newMain) + radius);
  const oLo = Math.floor(oldOther - radius);
  const oHi = Math.floor(newOther + radius);

  let collided = false;
  for (let a = lo; a <= hi && !collided; a++) {
    for (let b = oLo; b <= oHi; b++) {
      const cell = axis === 'x' ? grid[b][a] : grid[a][b];
      if (cell === C.TILES.WALL) { collided = true; break; }
    }
  }

  if (collided) {
    newVel[axis] = 0;
    newPos[axis] = oldMain;
  } else {
    newPos[axis] = newMain;
    newPos[other] = newOther;
  }

  return { pos: newPos, vel: newVel, collided };
};

