// js/preview.js — prévia FPS funcional do mapa (debug/visualização, não o jogo final)
// Usa módulos já prontos: engine, map, move, input. W3+ constrói o jogo completo.
import * as THREE from '../vendor/three.module.js';
import C from './constants.js';
import { createEngine } from './engine.js';
import { buildLevel, cellAt } from './map.js';
import { Input } from './input.js';
import { applyGravity, applyFriction, accelerate, moveAxis, tryJump, cameraBob } from './move.js';

const canvas = document.getElementById('game');
const { scene, camera, world, createLoop } = createEngine(canvas);
const level = buildLevel();
const grid = level.grid;
const input = new Input(canvas);

// WHY: cores por tipo de pickup (visão rápida do que é cada item)
const PICKUP_COLORS = { H: 0x44ff44, A: 0x4488ff, W: 0xffcc00 };

// WHY: materiais compartilhados (menos alocação por tile)
const MAT = {
  wall: new THREE.MeshLambertMaterial({ color: 0x555555 }),
  door: new THREE.MeshLambertMaterial({ color: 0x8a6a3a }),
  lava: new THREE.MeshLambertMaterial({ color: 0xff4400, emissive: 0xaa2200 }),
  floor: new THREE.MeshLambertMaterial({ color: 0x33333a }),
  exit: new THREE.MeshLambertMaterial({ color: 0x44ffcc, emissive: 0x116644 }),
  secret: new THREE.MeshLambertMaterial({ color: 0xff88ff, emissive: 0x550044 }),
  pickup: (color) => new THREE.MeshLambertMaterial({ color }),
};

const G = 0.95; // meio-tile de folga na colisão

// WHY: constrói a geometria estática do mapa (paredes, chão, lava, itens)
const buildWorld = () => {
  const floorGeo = new THREE.PlaneGeometry(C.MAP.gridW, C.MAP.gridH);
  const floor = new THREE.Mesh(floorGeo, MAT.floor);
  floor.rotation.x = -Math.PI / 2;
  floor.position.set(C.MAP.gridW / 2 - 0.5, 0, C.MAP.gridH / 2 - 0.5);
  world.add(floor);

  const wallGeo = new THREE.BoxGeometry(1, 2.2, 1);
  const doorGeo = new THREE.BoxGeometry(0.92, 2.2, 0.92);
  const lavaGeo = new THREE.BoxGeometry(0.98, 0.04, 0.98);
  const itemGeo = new THREE.BoxGeometry(0.34, 0.34, 0.34);

  let torchCount = 0;
  for (let z = 0; z < C.MAP.gridH; z++) {
    for (let x = 0; x < C.MAP.gridW; x++) {
      const ch = grid[z][x];
      const px = x;
      const pz = z;
      if (ch === C.TILES.WALL) {
        const m = new THREE.Mesh(wallGeo, MAT.wall);
        m.position.set(px, 1.1, pz);
        world.add(m);
      } else if (ch === C.TILES.DOOR) {
        const m = new THREE.Mesh(doorGeo, MAT.door);
        m.position.set(px, 1.1, pz);
        world.add(m);
      } else if (ch === C.TILES.LAVA) {
        const m = new THREE.Mesh(lavaGeo, MAT.lava);
        m.position.set(px, 0.02, pz);
        world.add(m);
      } else if (ch === C.TILES.EXIT) {
        const m = new THREE.Mesh(itemGeo, MAT.exit);
        m.position.set(px, 0.4, pz);
        world.add(m);
      } else if (ch === C.TILES.SECRET) {
        const m = new THREE.Mesh(itemGeo, MAT.secret);
        m.position.set(px, 0.4, pz);
        world.add(m);
      } else if (ch === C.TILES.TORCH) {
        const light = new THREE.PointLight(C.LIGHT.torchColor, C.LIGHT.torchIntensity, C.LIGHT.torchDist);
        light.position.set(px, 1.6, pz);
        world.add(light);
        torchCount++;
      } else if (PICKUP_COLORS[ch]) {
        const m = new THREE.Mesh(itemGeo, MAT.pickup(PICKUP_COLORS[ch]));
        m.position.set(px, 0.4, pz);
        world.add(m);
      }
    }
  }
  return torchCount;
};

const torchCount = buildWorld();

// WHY: estado do jogador (posição em coordenadas de tile: x=col, y=row)
const player = {
  pos: { x: level.playerSpawn.x + 0.5, y: level.playerSpawn.z + 0.5 },
  vel: { x: 0, y: 0 },
  onGround: true,
  hp: 100,
};

const hudPos = document.getElementById('pos');
const hudHelp = document.getElementById('help');

// WHY: HUD mínimo — posição, tochas, dano de lava
const updateHud = (dt) => {
  const tile = cellAt(grid, Math.floor(player.pos.x), Math.floor(player.pos.y));
  const lava = tile === C.TILES.LAVA;
  if (lava) player.hp -= 12 * dt;
  const posInfo = `x=${player.pos.x.toFixed(1)} z=${player.pos.y.toFixed(1)} · tile=${tile} · tochas=${torchCount} · HP=${Math.max(0, player.hp).toFixed(0)}`;
  hudPos.textContent = posInfo;
  hudPos.style.color = lava ? '#ff4444' : '#aacccc';
  if (player.hp <= 0) {
    hudHelp.textContent = '☠ VOCÊ CAIU NA LAVA — recarregue a página';
  }
};

// WHY: integra física do move.js com o grid (colisão por eixo)
const step = (dt) => {
  const wish = input.getAxis();
  const yaw = input.yaw;
  // WHY: direção desejada no espaço do mundo (R_y(+yaw) — lição ciclo 1)
  const wishX = wish.z * Math.sin(yaw) + wish.x * Math.cos(yaw);
  const wishY = wish.z * Math.cos(yaw) - wish.x * Math.sin(yaw);

  const speed = input.isDown('ShiftLeft') ? C.PHYSICS.runSpeed : C.PHYSICS.walkSpeed;
  accelerate(player.vel, { x: wishX, y: wishY }, C.PHYSICS.accel * speed, dt);
  applyFriction(player.vel, dt, player.onGround);
  if (input.isDown('Space')) tryJump(player.vel, player.onGround);

  moveAxis(player.pos, player.vel, 'x', dt, grid, G);
  moveAxis(player.pos, player.vel, 'y', dt, grid, G);
  player.vel.y = 0; // WHY: sem gravidade no preview (top-down 2D no grid)
  player.onGround = true;

  updateHud(dt);
};

// WHY: renderiza câmera FPS (posição 3D a partir do tile 2D + bob)
const render = (alpha) => {
  const bob = cameraBob(performance.now() / 1000, input.getAxis().x !== 0 || input.getAxis().z !== 0, 1);
  camera.position.set(
    player.pos.x,
    C.PLAYER.height + bob.y,
    player.pos.y
  );
  camera.rotation.order = 'YXZ';
  camera.rotation.y = -input.yaw;
  camera.rotation.x = input.pitch;
};

createLoop(step, render);

