// js/player.js — PlayerEntity (W3): FSM MENU/PLAYING, física, bob, pickups
import C from './constants.js';
import {
  applyGravity,
  applyFriction,
  accelerate,
  moveAxis,
  tryJump,
  cameraBob,
} from './move.js';

const { floor, min, max } = Math;

class PlayerEntity {
  constructor(level, input, weapons) {
    const s = level.playerSpawn;
    // WHY: centro do tile (spawn.x/z são índices inteiros do grid)
    this.pos = { x: s.x + 0.5, z: s.z + 0.5 };
    this.y = 0;
    this.vel = { x: 0, z: 0, y: 0 };
    this.yaw = s.yaw ?? -Math.PI / 2;
    this.pitch = 0;
    this.hp = C.PLAYER.startHp;
    this.armor = C.PLAYER.startArmor;
    this.onGround = true;
    this.state = 'MENU'; // FSM: MENU -> PLAYING
    this.bobTime = 0;
    this.input = input;
    this.weapons = weapons;
    this.level = level;
  }

  // WHY: FSM — transições explícitas (lição 5: compare uppercase, comente cada transição)
  start() { this.state = 'PLAYING'; }
  pause() { this.state = 'MENU'; }

  isMoving() {
    return Math.abs(this.vel.x) > 0.05 || Math.abs(this.vel.z) > 0.05;
  }

  update(dt) {
    if (this.state !== 'PLAYING') return;
    const wish = this.input.getAxis();
    const yaw = this.input.yaw;

    // WHY: R_y(+yaw) — lição 1 do ciclo 1 (direção desejada no espaço do mundo)
    const wishX = wish.z * Math.sin(yaw) + wish.x * Math.cos(yaw);
    const wishZ = wish.z * Math.cos(yaw) - wish.x * Math.sin(yaw);

    const speed = this.input.isDown('ShiftLeft') ? C.PHYSICS.runSpeed : C.PHYSICS.walkSpeed;
    accelerate(this.vel, { x: wishX, z: wishZ }, C.PHYSICS.accel * speed, dt);
    applyFriction(this.vel, dt, this.onGround);
    if (this.input.isDown('Space')) tryJump(this.vel, this.onGround);
    applyGravity(this.vel, dt);

    // WHY: colisão horizontal por eixo (moveAxis resolve AABB contra o grid)
    const rX = moveAxis(this.pos, { x: this.vel.x, y: this.vel.z }, 'x', dt, this.level.grid, C.PLAYER.radius);
    this.pos = rX.pos;
    this.vel.x = rX.vel.x;
    this.vel.z = rX.vel.y;
    const rZ = moveAxis(this.pos, { x: this.vel.x, y: this.vel.z }, 'y', dt, this.level.grid, C.PLAYER.radius);
    this.pos = rZ.pos;
    this.vel.x = rZ.vel.x;
    this.vel.z = rZ.vel.y;

    // WHY: altura vertical — chão em y=0, sem teto no mapa
    this.y += this.vel.y * dt;
    if (this.y <= 0) {
      this.y = 0;
      this.vel.y = 0;
      this.onGround = true;
    } else if (this.vel.y !== 0) {
      this.onGround = false;
    }

    if (this.isMoving()) this.bobTime += dt;
    this.yaw = yaw;
    this.pitch = this.input.pitch;

    this.stepHazards(dt);
    this.collectPickups();
  }

  // WHY: lava causa dano contínuo (tile LAVA do grid)
  stepHazards(dt) {
    const tile = this.level.grid[floor(this.pos.z)][floor(this.pos.x)];
    if (tile === C.TILES.LAVA) this.damage(12 * dt);
  }

  collectPickups() {
    const remaining = [];
    for (const p of this.level.pickups) {
      const d = Math.hypot(p.x + 0.5 - this.pos.x, p.z + 0.5 - this.pos.z);
      if (d < 0.6) {
        if (p.type === C.TILES.HEALTH) this.hp = min(C.PLAYER.startHp, this.hp + 25);
        else if (p.type === C.TILES.ARMOR) this.armor = min(100, this.armor + 25);
        else if (p.type === C.TILES.WEAPON) this.weapons.addAmmo('all', 20);
      } else {
        remaining.push(p);
      }
    }
    this.level.pickups = remaining;
  }

  // WHY: armadura absorve 50% do dano antes do HP (DOOM clássico)
  damage(amount) {
    if (this.armor > 0) {
      const absorbed = min(this.armor, amount * 0.5);
      this.armor -= absorbed;
      amount -= absorbed;
    }
    this.hp = max(0, this.hp - Math.round(amount));
    return this.hp;
  }

  viewY() {
    return C.PLAYER.height + cameraBob(this.bobTime, this.isMoving(), 1).y;
  }
}

export { PlayerEntity };

