// js/weapons.js — WeaponSystem (W3): Fist, Pistol, Shotgun, Rocket + munição
import C from './constants.js';

const { floor, min } = Math;

// WHY: raycast DDA contra o grid (hitscan/spread) — retorna ponto de impacto
const raycast = (player, grid, spread = 0) => {
  const yaw = player.yaw + (Math.random() - 0.5) * 2 * spread;
  const dx = Math.sin(yaw);
  const dz = Math.cos(yaw);
  let x = player.pos.x;
  let z = player.pos.z;
  let dist = 0;
  while (dist < 60) {
    x += dx * 0.05;
    z += dz * 0.05;
    dist += 0.05;
    const tx = floor(x);
    const tz = floor(z);
    if (tx < 0 || tz < 0 || tx >= C.MAP.gridW || tz >= C.MAP.gridH) break;
    const tile = grid[tz][tx];
    if (tile === C.TILES.WALL || tile === C.TILES.DOOR) {
      return { x, z, dist, hit: true, tile };
    }
  }
  return { x, z, dist, hit: false, tile: null };
};

class WeaponSystem {
  constructor() {
    this.inventory = ['fist', 'pistol', 'shotgun', 'rocket'];
    this.current = 0;
    this.ammo = { fist: Infinity, pistol: 50, shotgun: 12, rocket: 4 };
    this.cooldown = 0;
  }

  get weapon() { return C.WEAPON[this.inventory[this.current]]; }
  get name() { return this.weapon.name; }
  get key() { return this.inventory[this.current]; }

  update(dt) {
    this.cooldown = Math.max(0, this.cooldown - dt);
  }

  canFire() {
    const w = this.weapon;
    return this.cooldown <= 0 && (this.key === 'fist' || this.ammo[this.key] >= w.ammoCost);
  }

  switchWeapon(i) {
    if (i >= 0 && i < this.inventory.length) this.current = i;
  }

  // WHY: tipo 'all' distribui munição para todas as armas de munição (pickup W)
  addAmmo(type, qty) {
    if (type === 'all') {
      for (const k of ['pistol', 'shotgun', 'rocket']) {
        this.ammo[k] = min(C.WEAPON[k].maxAmmo, this.ammo[k] + qty);
      }
      return;
    }
    if (!C.WEAPON[type]) return;
    this.ammo[type] = min(C.WEAPON[type].maxAmmo, this.ammo[type] + qty);
  }

  fire(player, grid) {
    if (!this.canFire()) return null;
    const w = this.weapon;
    const key = this.key;
    this.cooldown = w.rate;
    if (key !== 'fist') this.ammo[key] -= w.ammoCost;

    switch (w.type) {
      case 'melee':
        return { type: 'melee', weapon: key, damage: w.damage, range: w.range };
      case 'hitscan':
        return { type: 'hitscan', weapon: key, damage: w.damage, hit: raycast(player, grid) };
      case 'spread': {
        const pellets = [];
        for (let i = 0; i < w.pellets; i++) pellets.push(raycast(player, grid, w.spread));
        return { type: 'spread', weapon: key, damage: w.damage, pellets };
      }
      case 'projectile':
        return {
          type: 'projectile',
          weapon: key,
          damage: w.damage,
          splash: w.splash,
          proj: {
            x: player.pos.x,
            z: player.pos.z,
            y: player.viewY ? 1.0 : 1.0,
            dx: Math.sin(player.yaw),
            dz: Math.cos(player.yaw),
            speed: 14,
            dist: 0,
          },
        };
      default:
        return null;
    }
  }
}

export { WeaponSystem, raycast };

