// tests/weapons.test.mjs — W3: WeaponSystem + PlayerEntity
import { test, describe, it } from 'node:test';
import assert from 'node:assert/strict';
import C from '../js/constants.js';
import { buildLevel } from '../js/map.js';
import { WeaponSystem } from '../js/weapons.js';
import { PlayerEntity } from '../js/player.js';

const STEP = C.PHYSICS.step;

// WHY: input mock — o Input real depende de canvas/DOM (testes em Node puro)
const mkInput = (over = {}) => ({
  getAxis: () => over.axis ?? { x: 0, z: 0 },
  isDown: () => over.down ?? false,
  yaw: over.yaw ?? 0,
  pitch: over.pitch ?? 0,
});

const mkLevel = () => {
  const level = buildLevel();
  return level;
};

describe('WeaponSystem — stats exatos (C.WEAPON)', () => {
  it('arma inicial é fist com stats exatos', () => {
    const w = new WeaponSystem();
    assert.equal(w.key, 'fist');
    assert.equal(w.name, C.WEAPON.fist.name);
    assert.equal(w.weapon.damage, C.WEAPON.fist.damage);
    assert.equal(w.weapon.rate, C.WEAPON.fist.rate);
  });

  it('pistol/shotgun/rocket existem com stats exatos', () => {
    const w = new WeaponSystem();
    w.switchWeapon(1);
    assert.equal(w.key, 'pistol');
    assert.equal(w.weapon.damage, C.WEAPON.pistol.damage);
    assert.equal(w.weapon.maxAmmo, C.WEAPON.pistol.maxAmmo);
    w.switchWeapon(2);
    assert.equal(w.key, 'shotgun');
    assert.equal(w.weapon.pellets, C.WEAPON.shotgun.pellets);
    w.switchWeapon(3);
    assert.equal(w.key, 'rocket');
    assert.equal(w.weapon.splash, C.WEAPON.rocket.splash);
  });
});

describe('WeaponSystem — munição e rate', () => {
  it('fist não consome munição e atira melee (dano 20, range 2.2)', () => {
    const w = new WeaponSystem();
    const level = mkLevel();
    const player = new PlayerEntity(level, mkInput(), w);
    player.start();
    const r = w.fire(player, level.grid);
    assert.equal(r.type, 'melee');
    assert.equal(r.damage, C.WEAPON.fist.damage);
    assert.equal(r.range, C.WEAPON.fist.range);
    assert.equal(w.ammo.fist, Infinity);
  });

  it('pistol consome 1 de munição por tiro e respeita rate', () => {
    const w = new WeaponSystem();
    w.switchWeapon(1);
    const level = mkLevel();
    const player = new PlayerEntity(level, mkInput({ yaw: Math.PI }), w);
    player.start();
    const r1 = w.fire(player, level.grid);
    assert.equal(r1.type, 'hitscan');
    assert.equal(w.ammo.pistol, 49);
    // rate 0.15 — segundo tiro imediato é bloqueado
    assert.equal(w.fire(player, level.grid), null);
    w.update(0.16);
    assert.ok(w.canFire());
  });

  it('shotgun dispara 7 pellets (spread)', () => {
    const w = new WeaponSystem();
    w.switchWeapon(2);
    const level = mkLevel();
    const player = new PlayerEntity(level, mkInput({ yaw: Math.PI }), w);
    player.start();
    const r = w.fire(player, level.grid);
    assert.equal(r.type, 'spread');
    assert.equal(r.pellets.length, C.WEAPON.shotgun.pellets);
    assert.equal(w.ammo.shotgun, 11);
  });

  it('rocket dispara projétil com dano 30 e splash 2.0', () => {
    const w = new WeaponSystem();
    w.switchWeapon(3);
    const level = mkLevel();
    const player = new PlayerEntity(level, mkInput({ yaw: Math.PI }), w);
    player.start();
    const r = w.fire(player, level.grid);
    assert.equal(r.type, 'projectile');
    assert.equal(r.damage, C.WEAPON.rocket.damage);
    assert.equal(r.splash, C.WEAPON.rocket.splash);
    assert.equal(w.ammo.rocket, 3);
  });

  it('sem munição não atira (fist continua ok)', () => {
    const w = new WeaponSystem();
    w.ammo.pistol = 0;
    w.switchWeapon(1);
    const level = mkLevel();
    const player = new PlayerEntity(level, mkInput(), w);
    player.start();
    assert.equal(w.canFire(), false);
    assert.equal(w.fire(player, level.grid), null);
    w.switchWeapon(0);
    assert.equal(w.canFire(), true);
  });

  it('addAmmo respeita maxAmmo e tipo all distribui', () => {
    const w = new WeaponSystem();
    w.addAmmo('pistol', 1000);
    assert.equal(w.ammo.pistol, C.WEAPON.pistol.maxAmmo);
    w.addAmmo('all', 10);
    assert.equal(w.ammo.pistol, C.WEAPON.pistol.maxAmmo);
    assert.equal(w.ammo.shotgun, 22);
    assert.equal(w.ammo.rocket, 14);
  });
});

describe('WeaponSystem — hitscan acerta parede', () => {
  it('raycast do spawn olhando -Z encontra parede a < 5 tiles', () => {
    const w = new WeaponSystem();
    w.switchWeapon(1);
