// js/enemies.js — W4: 6 inimigos com FSM idle/alert/chase/attack/pain/death
import C from './constants.js';
import { moveAxis } from './move.js';
import { hasLineOfSight } from './map.js';

const { floor, max, min, hypot } = Math;

// WHY: taxa de ataque por tipo (default 1.0s — não está no C.ENEMY)
const ATTACK_RATES = { projectile: 1.2, hitscan: 1.0, melee: 0.8, double: 1.4, arc: 1.1, rocket: 1.3 };

// WHY: direção unitária inimigo -> player
const dirTo = (from, to) => {
  const dx = to.x - from.x;
  const dz = to.z - from.z;
  const len = hypot(dx, dz) || 1;
  return { x: dx / len, z: dz / len };
};

class Enemy {
  constructor(kind, x, z, doors = []) {
    this.kind = kind;
    this.stats = C.ENEMY[kind];
    this.pos = { x, z }; // centro do tile (como o player)
    this.yaw = 0;
    this.hp = this.stats.hp;
    this.state = 'idle'; // FSM: idle -> chase <-> attack | -> pain -> chase | -> death
    this.timer = 0;
    this.attackCooldown = 0;
    this.painTimer = 0;
    this.dead = false;
    this.doors = doors;
    this.sightRange = 12;
    this.attackRange = this.stats.type === 'melee' ? 1.5 : 8;
  }

  get alive() { return !this.dead; }

  // WHY: FSM — transição explícita com timer zerado (lição 5: comente cada transição)
  setState(s) { this.state = s; this.timer = 0; }

  damage(amount) {
    if (this.dead) return;
    this.hp -= amount;
    if (this.hp <= 0) {
      this.hp = 0;
      this.dead = true;
      this.state = 'death';
      return;
    }
    this.painTimer = 0.2;
    this.setState('pain');
  }

  // WHY: LOS até o player — DDA do map bloqueia parede/porta fechada/lava (W4)
  canSee(grid, player) {
    const dist = hypot(player.pos.x - this.pos.x, player.pos.z - this.pos.z);
    if (dist > this.sightRange) return false;
    return hasLineOfSight(grid, this.pos.x, this.pos.z, player.pos.x, player.pos.z, this.doors);
  }

  attackRate() { return ATTACK_RATES[this.stats.type] ?? 1.0; }

  // WHY: ataque por tipo (projectile/hitscan/melee/double/arc/rocket)
  fireAt(player, grid) {
    const s = this.stats;
    switch (s.type) {
      case 'melee':
        return { type: 'melee', damage: s.dmg, from: { ...this.pos }, target: { ...player.pos } };
      case 'hitscan':
        // WHY: hitscan só acerta se há LOS no momento do disparo
        return { type: 'hitscan', damage: this.canSee(grid, player) ? s.dmg : 0, from: { ...this.pos } };
