    if (this.state === 'idle') {
      if (seen) this.setState('chase');
      return null;
    }

    if (this.state === 'chase') {
      if (!seen) { this.setState('idle'); return null; }
      const d = dirTo(this.pos, player.pos);
      this.yaw = Math.atan2(d.x, d.z);
      // WHY: persegue com colisão por eixo (mesmo padrão do player)
      const rX = moveAxis(this.pos, { x: d.x * this.stats.speed, y: d.z * this.stats.speed }, 'x', dt, grid, this.stats.size * 0.45);
