// tests/enemies.test.mjs — W4: 6 inimigos, FSM, LOS, spawn 3×3
import { test, describe, it } from 'node:test';
import assert from 'node:assert/strict';
import C from '../js/constants.js';
import { buildLevel } from '../js/map.js';
import { Enemy, spawnEnemies } from '../js/enemies.js';

const STEP = C.PHYSICS.step;

// WHY: grids pequenos para testar LOS de forma determinística
const arena = ['#####', '#...#', '#...#', '#...#', '#####'];
const block = ['#####', '#.#.#', '#.#.#', '#.#.#', '#####'];
const lavaGrid = ['#####', '#L#.#', '#L#.#', '#L#.#', '#####'];
const doorGrid = ['#####', '#D#.#', '#D#.#', '#D#.#', '#####'];

const mkPlayer = (x, z) => ({ pos: { x, z } });
const mkEnemy = (kind, x = 1.5, z = 2.5, doors = []) => new Enemy(kind, x, z, doors);

describe('Enemy — stats exatos (C.ENEMY)', () => {
  it('os 6 inimigos têm stats idênticos ao contrato', () => {
    for (const kind of Object.keys(C.ENEMY)) {
      const e = mkEnemy(kind);
      assert.deepEqual(e.stats, C.ENEMY[kind], `stats de ${kind}`);
      assert.equal(e.hp, C.ENEMY[kind].hp);
      assert.equal(e.alive, true);
    }
  });
});

describe('Enemy — FSM', () => {
  it('idle -> chase quando vê o player', () => {
    const e = mkEnemy('imp');
    const r = e.update(STEP, mkPlayer(3.5, 2.5), arena);
    assert.equal(e.state, 'chase');
    assert.equal(r, null);
  });

  it('idle permanece quando não vê (parede bloqueia)', () => {
    const e = mkEnemy('imp');
    e.update(STEP, mkPlayer(3.5, 2.5), block);
    assert.equal(e.state, 'idle');
  });

  it('chase -> attack dispara melee (demon, dist < 1.5) e volta a chase', () => {
    const e = mkEnemy('demon', 1.5, 2.5);
    const player = mkPlayer(2.5, 2.5);
    e.update(STEP, player, arena); // idle -> attack (transiente)
    const evt = e.update(STEP, player, arena); // attack dispara
    assert.equal(evt.type, 'melee');
    assert.equal(evt.damage, C.ENEMY.demon.dmg);
    assert.equal(e.state, 'chase');
    // cooldown ativo impede ataque imediato
    e.update(STEP, player, arena);
    assert.equal(e.state, 'chase');
  });

  it('chase volta a idle quando perde visão', () => {
    const e = mkEnemy('imp');
    const player = mkPlayer(3.5, 2.5);
    e.update(STEP, player, arena); // -> chase
    e.update(STEP, mkPlayer(1.5, 1.5), block); // perdeu visão (bloco)
    assert.equal(e.state, 'idle');
  });

  it('pain interrompe e retoma chase ao terminar', () => {
    const e = mkEnemy('imp');
    e.damage(5);
    assert.equal(e.hp, C.ENEMY.imp.hp - 5);
    assert.equal(e.state, 'pain');
    e.update(0.05, mkPlayer(3.5, 2.5), arena); // ainda em pain
    assert.equal(e.state, 'pain');
    e.update(0.3, mkPlayer(3.5, 2.5), arena); // pain expirou, vê player
    assert.equal(e.state, 'chase');
  });

  it('death é terminal e não age', () => {
    const e = mkEnemy('baron');
    e.damage(999);
    assert.equal(e.dead, true);
    assert.equal(e.hp, 0);
    assert.equal(e.state, 'death');
    const r = e.update(STEP, mkPlayer(3.5, 2.5), arena);
    assert.equal(r, null);
    assert.equal(e.state, 'death');
  });

  it('hitscan (trooper) só acerta com LOS no momento do disparo', () => {
    const e = mkEnemy('trooper');
    const player = mkPlayer(3.5, 2.5);
    e.update(STEP, player, arena); // chase
    e.setState('attack');
    const evt = e.update(STEP, player, arena);
    assert.equal(evt.type, 'hitscan');
    assert.equal(evt.damage, C.ENEMY.trooper.dmg); // com LOS
    e.setState('attack');
    const evt2 = e.update(STEP, mkPlayer(3.5, 2.5), block); // sem LOS
    assert.equal(evt2.damage, 0);
  });

  it('double (baron) dispara 2 projéteis; rocket (revenant) projétil rápido', () => {
    const baron = mkEnemy('baron');
    baron.setState('attack');
    const evt = baron.update(STEP, mkPlayer(3.5, 2.5), arena);
    assert.equal(evt.type, 'double');
    assert.equal(evt.shots, 2);
    const rev = mkEnemy('revenant');
    rev.setState('attack');
    const evt2 = rev.update(STEP, mkPlayer(3.5, 2.5), arena);
    assert.equal(evt2.type, 'projectile');
    assert.equal(evt2.speed, 12);
  });
});

describe('Enemy — line-of-sight', () => {
  it('parede bloqueia visão', () => {
    const e = mkEnemy('imp');
    assert.equal(e.canSee(block, mkPlayer(3.5, 2.5)), false);
  });

  it('lava bloqueia visão (W4 acceptance)', () => {
    const e = mkEnemy('imp');
    assert.equal(e.canSee(lavaGrid, mkPlayer(3.5, 2.5)), false);
  });

  it('porta fechada bloqueia visão; aberta libera', () => {
    const doors = [{ x: 2, z: 1, state: 'closed' }, { x: 2, z: 2, state: 'closed' }, { x: 2, z: 3, state: 'closed' }];
    const e = mkEnemy('imp', 1.5, 2.5, doors);
    assert.equal(e.canSee(doorGrid, mkPlayer(3.5, 2.5)), false);
    doors.forEach((d) => { d.state = 'open'; });
    assert.equal(e.canSee(doorGrid, mkPlayer(3.5, 2.5)), true);
  });

  it('LOS livre retorna true', () => {
    const e = mkEnemy('imp');
    assert.equal(e.canSee(arena, mkPlayer(3.5, 2.5)), true);
  });
});

describe('spawnEnemies — grid 3×3 no centro', () => {
  it('spawna 9 inimigos em tiles livres', () => {
    const level = buildLevel();
    const enemies = spawnEnemies(level, 'imp', 9);
    assert.equal(enemies.length, 9);
    for (const e of enemies) {
      const tx = Math.floor(e.pos.x);
      const tz = Math.floor(e.pos.z);
      const tile = level.grid[tz][tx];
      assert.notEqual(tile, C.TILES.WALL);
      assert.notEqual(tile, C.TILES.DOOR);
      assert.ok(tx >= 16 && tx <= 20, `x ${tx} dentro do 3×3 ampliado`);
    }
  });

  it('respeita o limite count', () => {
    const level = buildLevel();
    const enemies = spawnEnemies(level, 'demon', 4);
    assert.equal(enemies.length, 4);
    assert.equal(enemies[0].kind, 'demon');
  });
});

