// js/particles.js — W5: sistema de partículas (explosões, sangue, sparkles)
// Dados puros + render Canvas2D com ctx injetado (testável em node)

// WHY: converte 0xRRGGBB para css (#rrggbb) — canvas precisa string
const hexToCss = (n) => `#${n.toString(16).padStart(6, '0')}`;

class Particle {
  constructor(x, z, y = 0.5, opts = {}) {
    this.x = x;
    this.z = z;
    this.y = y;
    this.vx = opts.vx ?? 0;
    this.vz = opts.vz ?? 0;
    this.vy = opts.vy ?? 0;
    this.life = opts.life ?? 0.6;
    this.maxLife = this.life;
    this.color = opts.color ?? 0xffaa33;
    this.size = opts.size ?? 0.1;
    this.gravity = opts.gravity ?? 0;
  }

  get alive() { return this.life > 0; }

  update(dt) {
    this.life -= dt;
    if (!this.alive) return;
    this.vy += this.gravity * dt;
    this.x += this.vx * dt;
    this.z += this.vz * dt;
    this.y += this.vy * dt;
  }
}

class ParticleSystem {
  constructor() { this.particles = []; }

  get aliveCount() { return this.particles.filter((p) => p.alive).length; }

  spawn(x, z, y, opts) { this.particles.push(new Particle(x, z, y, opts)); }

  // WHY: explosão radial com velocidade aleatória (fireball estilo DOOM)
  explosion(x, z, y = 0.5, count = 12, power = 3) {
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const v = power * (0.3 + Math.random() * 0.7);
      this.spawn(x, z, y, {
        vx: Math.cos(a) * v, vz: Math.sin(a) * v, vy: Math.random() * 2,
        life: 0.4 + Math.random() * 0.4, color: 0xff8800, size: 0.15, gravity: -6,
      });
    }
  }

  blood(x, z, y = 0.5, count = 8) {
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const v = 1 + Math.random();
      this.spawn(x, z, y, {
        vx: Math.cos(a) * v, vz: Math.sin(a) * v, vy: Math.random(),
        life: 0.5, color: 0xcc2222, size: 0.08, gravity: -4,
      });
    }
  }

  spark(x, z, y = 0.5, count = 5) {
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const v = 2 + Math.random() * 2;
      this.spawn(x, z, y, {
        vx: Math.cos(a) * v, vz: Math.sin(a) * v, vy: Math.random() * 2,
        life: 0.2, color: 0xffdd44, size: 0.05,
      });
    }
  }

  update(dt) {
    for (const p of this.particles) p.update(dt);
    // WHY: remove mortos (compactação in-place — mantém aliveCount fiel)
    this.particles = this.particles.filter((p) => p.alive);
  }

  render(ctx, scale = 1) {
    for (const p of this.particles) {
      ctx.fillStyle = hexToCss(p.color);
      ctx.globalAlpha = Math.max(0, p.life / p.maxLife);
      ctx.fillRect((p.x - p.size) * scale, (p.z - p.size) * scale, p.size * 2 * scale, p.size * 2 * scale);
    }
    ctx.globalAlpha = 1;
  }
}

export { Particle, ParticleSystem, hexToCss };

