// js/audio.js — W5: WebAudio procedural (6 sons + música) — zero arquivos externos
// AudioContext injetável: browser real ou null (node/tests) — estado sempre rastreável

// WHY: sons sintetizados via osciladores + slide de frequência — requisito "sem arquivos"
const SOUNDS = {
  shoot: { type: 'square', freq: 440, dur: 0.08, slide: -200 },
  enemyShoot: { type: 'sawtooth', freq: 220, dur: 0.1, slide: -80 },
  damage: { type: 'triangle', freq: 180, dur: 0.15, slide: -60 },
  pickup: { type: 'sine', freq: 660, dur: 0.12, slide: 220 },
  door: { type: 'square', freq: 90, dur: 0.2, slide: -30 },
  explosion: { type: 'sawtooth', freq: 120, dur: 0.35, slide: -90 },
};

class AudioEngine {
  constructor(ctx = null) {
    this.ctx = ctx;
    this.muted = false;
    this.lastPlayed = null;
    this.queue = [];
    this.musicPlaying = false;
  }

  // WHY: cria o contexto sob demanda (autoplay policy do browser exige gesto do usuário)
  ensureCtx() {
    if (this.ctx) return this.ctx;
    if (typeof window !== 'undefined' && window.AudioContext) {
      this.ctx = new window.AudioContext();
    }
    return this.ctx;
  }

  play(name) {
    this.lastPlayed = name;
    this.queue.push(name);
    const s = SOUNDS[name];
    if (!s) return false;
    const ctx = this.ensureCtx();
    if (!ctx || this.muted) return false;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = s.type;
    osc.frequency.setValueAtTime(s.freq, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(Math.max(30, s.freq + s.slide), ctx.currentTime + s.dur);
    gain.gain.setValueAtTime(0.15, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + s.dur);
    osc.connect(gain).connect(ctx.destination);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + s.dur);
    return true;
  }

  setMuted(m) { this.muted = m; }

  toggleMute() { this.muted = !this.muted; return this.muted; }

  startMusic() { this.musicPlaying = true; }

  stopMusic() { this.musicPlaying = false; }

