// js/audio.js — W5: WebAudio procedural (6 sons + música) — zero arquivos externos
// AudioContext injetável: browser real ou null (node/tests) — estado sempre rastreável

// WHY: sons sintetizados via osciladores + slide de frequência — requisito "sem arquivos"
const SOUNDS = {
  shoot: { type: 'square', freq: 440, dur: 0.08, slide: -200 },
  enemyShoot: { type: 'sawtooth', freq: 220, dur: 0.1, slide: -80 },
  damage: { type: 'triangle', freq: 180, dur: 0.15, slide: -60 },
  pickup: { type: 'sine', freq: 660, dur: 0.12, slide: 220 },
  door: { type: 'square', freq: 90, dur: 0.2, slide: -30 },
  explosion: { type: 'sawtooth', freq: 120, dur: 0.35, slide: -90 },
};

class AudioEngine {
  constructor(ctx = null) {
    this.ctx = ctx;
    this.muted = false;
    this.lastPlayed = null;
    this.queue = [];
    this.musicPlaying = false;
  }

  // WHY: cria o contexto sob demanda (autoplay policy do browser exige gesto do usuário)
  ensureCtx() {
    if (this.ctx) return this.ctx;
    if (typeof window !== 'undefined' && window.AudioContext) {
      this.ctx = new window.AudioContext();
    }
    return this.ctx;
  }

  play(name) {
    this.lastPlayed = name;
    this.queue.push(name);
    const s = SOUNDS[name];
    if (!s) return false;
    const ctx = this.ensureCtx();
    if (!ctx || this.muted) return false;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = s.type;
    osc.frequency.setValueAtTime(s.freq, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(Math.max(30, s.freq + s.slide), ctx.currentTime + s.dur);
    gain.gain.setValueAtTime(0.15, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + s.dur);
    osc.connect(gain).connect(ctx.destination);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + s.dur);
    return true;
  }

  setMuted(m) { this.muted = m; }

  toggleMute() { this.muted = !this.muted; return this.muted; }

  startMusic() { this.musicPlaying = true; }

  stopMusic() { this.musicPlaying = false; }

  // WHY: escala pentatônica menor — notas válidas para música procedural
  static scaleNote(i) {
    const root = 110;
    const steps = [0, 3, 5, 7, 10, 12];
    return root * Math.pow(2, steps[i % steps.length] / 12);
  }
}

export { AudioEngine, SOUNDS };

// js/minimap.js — W5: minimap Canvas2D (walls, doors, pickups, enemies, player)
import C from './constants.js';

// WHY: dados puros para render — testável em node sem canvas
const buildMinimapData = (level, player, enemies = [], pickups = []) => {
  const rows = level.grid.length;
  const cols = level.grid[0].length;
  const tiles = [];
  for (let z = 0; z < rows; z++) {
    for (let x = 0; x < cols; x++) {
      const ch = level.grid[z][x];
      if (ch !== C.TILES.FLOOR) tiles.push({ x, z, ch });
    }
  }
  return {
    cols,
    rows,
    tiles,
    doors: level.doors.map((d) => ({ x: d.x, z: d.z, open: d.state === 'open' })),
    pickups: pickups.map((p) => ({ x: p.x, z: p.z })),
    enemies: enemies.map((e) => ({ x: e.pos.x, z: e.pos.z, alive: e.alive })),
    player: { x: player.pos.x, z: player.pos.z, yaw: player.yaw ?? 0 },
  };
};

// WHY: cor do tile por tipo (paleta retro)
const tileColor = (ch) => {
  switch (ch) {
    case C.TILES.WALL: return '#888';
    case C.TILES.DOOR: return '#cc8833';
    case C.TILES.LAVA: return '#ff4422';
    case C.TILES.TORCH: return '#ffdd33';
    case C.TILES.EXIT: return '#33ff66';
    case C.TILES.SECRET: return '#aa66ff';
    default: return '#556';
  }
};

// WHY: renderiza em canvas 2D (ctx injetado; scale = pixels por tile)
const renderMinimap = (ctx, data, scale = 6) => {
  const w = data.cols * scale;
  const h = data.rows * scale;
  ctx.fillStyle = '#111';
  ctx.fillRect(0, 0, w, h);
  for (const t of data.tiles) {
    ctx.fillStyle = tileColor(t.ch);
    ctx.fillRect(t.x * scale, t.z * scale, scale, scale);
  }
  for (const p of data.pickups) {
    ctx.fillStyle = '#33ccff';
    ctx.fillRect(p.x * scale + scale / 4, p.z * scale + scale / 4, scale / 2, scale / 2);
  }
  for (const e of data.enemies) {
    if (!e.alive) continue;
    ctx.fillStyle = '#ff3333';
    ctx.fillRect(e.x * scale - 1, e.z * scale - 1, 3, 3);
  }
  // WHY: player — círculo + seta de direção (yaw)
  const px = data.player.x * scale;
  const pz = data.player.z * scale;
  ctx.fillStyle = '#33ff66';
  ctx.beginPath();
  ctx.arc(px, pz, 3, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#33ff66';
  ctx.beginPath();
  ctx.moveTo(px, pz);
  ctx.lineTo(px + Math.sin(data.player.yaw) * 8, pz + Math.cos(data.player.yaw) * 8);
  ctx.stroke();
  return { w, h };
};

export { buildMinimapData, renderMinimap, tileColor };

