// tests/particles.test.mjs — W5: sistema de partículas
import { test, describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { Particle, ParticleSystem, hexToCss } from '../js/particles.js';

// WHY: ctx mock registra chamadas — valida render sem canvas real
const mockCtx = () => {
  const calls = [];
  const ctx = {
    calls,
    fillStyle: '',
    globalAlpha: 1,
    fillRect(x, y, w, h) { calls.push(['fillRect', x, y, w, h]); },
  };
  return ctx;
};

describe('hexToCss', () => {
  it('converte 0xRRGGBB para #rrggbb', () => {
    assert.equal(hexToCss(0xffaa33), '#ffaa33');
    assert.equal(hexToCss(0x000000), '#000000');
    assert.equal(hexToCss(0xffffff), '#ffffff');
  });
});

describe('Particle', () => {
  it('life decresce com update e morto quando <= 0', () => {
    const p = new Particle(0, 0, 0.5, { life: 0.1 });
    assert.equal(p.alive, true);
    p.update(0.06);
    assert.equal(p.alive, true);
    p.update(0.06);
    assert.equal(p.alive, false);
  });

  it('gravidade afeta vy e posição muda', () => {
    const p = new Particle(0, 0, 1, { vy: 0, gravity: -10, life: 1 });
    p.update(0.1);
    assert.equal(p.vy, -1);
    assert.equal(p.y, 0.9);
  });
});

describe('ParticleSystem', () => {
  it('explosion spawna count partículas vivas', () => {
    const ps = new ParticleSystem();
    ps.explosion(5, 5, 0.5, 12, 3);
    assert.equal(ps.particles.length, 12);
    assert.equal(ps.aliveCount, 12);
  });

  it('blood e spark spawnam e morrem com update', () => {
    const ps = new ParticleSystem();
    ps.blood(1, 1);
    ps.spark(2, 2);
    assert.equal(ps.particles.length, 13);
    ps.update(5);
    assert.equal(ps.aliveCount, 0);
    assert.equal(ps.particles.length, 0);
  });

  it('render desenha um quadrado por partícula e restaura alpha', () => {
    const ps = new ParticleSystem();
    ps.spawn(10, 10, 0.5, { size: 0.1, life: 0.5, color: 0xff8800 });
    const ctx = mockCtx();
    ps.render(ctx, 10);
    assert.equal(ctx.calls.length, 1);
    assert.equal(ctx.calls[0][0], 'fillRect');
    assert.equal(ctx.globalAlpha, 1);
  });
});

