import { test, describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { AudioEngine, SOUNDS } from '../js/audio.js';

// WHY: mock de AudioContext registra osciladores criados — valida sintetização sem áudio real
const mockCtx = () => ({
  currentTime: 0,
  destination: { node: true },
  created: 0,
  createOscillator() {
    this.created += 1;
    return {
      type: '',
      frequency: { setValueAtTime() {}, exponentialRampToValueAtTime() {} },
      connect() { return { connect() {} }; },
      start() {}, stop() {},
    };
  },
  createGain() {
    return { gain: { setValueAtTime() {}, exponentialRampToValueAtTime() {} }, connect() { return { connect() {} }; } };
  },
});

describe('SOUNDS — 6 sons sem arquivos externos', () => {
  it('tem exatamente os 6 sons do contrato', () => {
    assert.deepEqual(Object.keys(SOUNDS).sort(), ['damage', 'door', 'enemyShoot', 'explosion', 'pickup', 'shoot']);
  });

  it('cada som tem type/freq/dur/slide válidos', () => {
    for (const [name, s] of Object.entries(SOUNDS)) {
      assert.ok(['square', 'sawtooth', 'triangle', 'sine'].includes(s.type), `${name}.type`);
      assert.ok(s.freq > 20 && s.freq < 2000, `${name}.freq`);
      assert.ok(s.dur > 0 && s.dur < 1, `${name}.dur`);
      assert.equal(typeof s.slide, 'number', `${name}.slide`);
    }
  });
});

describe('AudioEngine — sem contexto (node/tests)', () => {
  it('play registra lastPlayed e queue mesmo sem ctx; retorna false', () => {
    const a = new AudioEngine(null);
    assert.equal(a.play('shoot'), false);
    assert.equal(a.lastPlayed, 'shoot');
    assert.deepEqual(a.queue, ['shoot']);
  });

  it('som desconhecido retorna false sem crash', () => {
    const a = new AudioEngine(null);
    assert.equal(a.play('nope'), false);
  });
});

describe('AudioEngine — com ctx mock', () => {
  it('play sintetiza oscilador + gain e retorna true', () => {
    const ctx = mockCtx();
    const a = new AudioEngine(ctx);
    assert.equal(a.play('explosion'), true);
    assert.equal(ctx.created, 1);
    assert.equal(a.lastPlayed, 'explosion');
  });

  it('muted bloqueia síntese mas registra na fila', () => {
    const ctx = mockCtx();
    const a = new AudioEngine(ctx);
    a.setMuted(true);
    assert.equal(a.play('shoot'), false);
    assert.equal(ctx.created, 0);
    assert.deepEqual(a.queue, ['shoot']);
  });

  it('toggleMute alterna estado', () => {
    const a = new AudioEngine(null);
    assert.equal(a.toggleMute(), true);
    assert.equal(a.toggleMute(), false);
  });
});

describe('AudioEngine — música procedural', () => {
  it('startMusic/stopMusic controlam o flag', () => {
    const a = new AudioEngine(null);
    a.startMusic();
    assert.equal(a.musicPlaying, true);
    a.stopMusic();
    assert.equal(a.musicPlaying, false);
  });

  it('scaleNote gera notas ascendentes na pentatônica menor', () => {
    const n0 = AudioEngine.scaleNote(0);
    const n1 = AudioEngine.scaleNote(1);
    const n2 = AudioEngine.scaleNote(2);
    assert.ok(n0 < n1 && n1 < n2, 'notas ascendentes');
    assert.equal(n0, 110, 'raiz A2');
    assert.ok(n0 > 0);
  });
});

