// js/hud.js — W6: painel retro Canvas2D (barras HP/armor, ammo, weapon slot, score, crosshair)
// Dados puros + render com ctx injetado (testável em node)

// WHY: cores do painel retro — verde HP, azul armadura (DOOM clássico)
const COLORS = {
  hp: '#33ff33',
  armor: '#3366ff',
  ammo: '#ffcc33',
  bg: 'rgba(16,16,20,0.85)',
  text: '#fff',
  barBg: '#111',
  cross: '#ccffcc',
};

const WEAPON_NAMES = { fist: 'FIST', pistol: 'PISTOL', shotgun: 'SHOTGUN', rocket: 'ROCKET' };

// WHY: dados puros do HUD — testável sem canvas
const buildHudData = (player, weapons) => ({
  hp: Math.max(0, Math.round(player.hp ?? 0)),
  maxHp: player.maxHp ?? 100,
  armor: Math.max(0, Math.round(player.armor ?? 0)),
  maxArmor: player.maxArmor ?? 100,
  weapon: weapons.current,
  ammo: weapons.ammo[weapons.current],
  score: player.score ?? 0,
});

// WHY: render do painel (ctx injetado; w/h = dimensões do canvas)
const renderHud = (ctx, data, w, h) => {
  const pad = 16;
  const barW = 132;
  const barH = 9;

  // painel inferior
  ctx.fillStyle = COLORS.bg;
  ctx.fillRect(0, h - 26, w, 26);

  // barra HP (verde) — fundo + preenchimento proporcional
  ctx.fillStyle = COLORS.barBg;
  ctx.fillRect(pad, h - 21, barW, barH);
  ctx.fillStyle = COLORS.hp;
  ctx.fillRect(pad, h - 21, barW * Math.min(1, data.hp / data.maxHp), barH);

  // barra armor (azul)
  ctx.fillStyle = COLORS.barBg;
  ctx.fillRect(pad, h - 10, barW, barH);
  ctx.fillStyle = COLORS.armor;
  ctx.fillRect(pad, h - 10, barW * Math.min(1, data.armor / data.maxArmor), barH);

  // ammo + weapon slot (canto direito)
  ctx.fillStyle = COLORS.ammo;
  ctx.font = '14px monospace';
  ctx.textAlign = 'right';
  ctx.fillText(`${WEAPON_NAMES[data.weapon] ?? data.weapon} ${data.ammo}`, w - pad, h - 8);

  // score (acima do painel)
  ctx.fillStyle = COLORS.text;
  ctx.textAlign = 'left';
  ctx.fillText(`SCORE ${data.score}`, pad, h - 32);

  // crosshair (+ no centro)
  const cx = w / 2;
  const cy = h / 2;
  ctx.strokeStyle = COLORS.cross;
  ctx.beginPath();
  ctx.moveTo(cx - 5, cy);
  ctx.lineTo(cx + 5, cy);
  ctx.moveTo(cx, cy - 5);
  ctx.lineTo(cx, cy + 5);
  ctx.stroke();
};

export { buildHudData, renderHud, COLORS, WEAPON_NAMES };

