// js/game.js — W6: game loop fixed-step 60Hz + máquina de estados
// rAF injetável (browser real ou stub de teste); step() síncrono testável

const FIXED_DT = 1 / 60;
const MAX_FRAME = 0.25; // clamp contra tab switch (dt em segundos)

const STATES = { MENU: 'MENU', PLAYING: 'PLAYING', PAUSED: 'PAUSED', GAMEOVER: 'GAMEOVER', WIN: 'WIN' };

class Game {
  constructor({ update, render, requestFrame = null }) {
    this.update = update;
    this.render = render;
    // WHY: requestFrame injetável — browser usa rAF; testes usam stub/step direto
    this.requestFrame = requestFrame ?? ((cb) => {
      if (typeof window !== 'undefined' && window.requestAnimationFrame) window.requestAnimationFrame(cb);
    });
    this.state = STATES.MENU;
    this.time = 0;
    this.acc = 0;
    this.last = 0;
    this.frame = 0;
    this.running = false;
  }

  start() {
    if (this.running) return;
    this.running = true;
    this.last = performance.now();
    this.frame = 0;
    const loop = (now) => {
      if (!this.running) return;
      this.step(now);
      this.requestFrame(loop);
    };
    this.requestFrame(loop);
  }

  stop() { this.running = false; }

  // WHY: passo síncrono — acumula dt real e processa N passos fixos de 1/60
  step(now) {
    if (!this.running) return;
    const dt = Math.min(Math.max((now - this.last) / 1000, 0), MAX_FRAME);
    this.last = now;
    this.acc += dt;
    while (this.acc >= FIXED_DT) {
      this.update(FIXED_DT);
      this.time += FIXED_DT;
      this.acc -= FIXED_DT;
      this.frame += 1;
    }
    this.render();
  }

  // WHY: transições de estado (Menu→Play→Pause→GameOver/Win)
  startGame() { this.state = STATES.PLAYING; }
  pause() { if (this.state === STATES.PLAYING) this.state = STATES.PAUSED; }
  resume() { if (this.state === STATES.PAUSED) this.state = STATES.PLAYING; }
  togglePause() { if (this.state === STATES.PLAYING) this.pause(); else if (this.state === STATES.PAUSED) this.resume(); }
  gameOver() { this.state = STATES.GAMEOVER; }
  win() { this.state = STATES.WIN; }
}

export { Game, STATES, FIXED_DT };

