tool_input.content:
// js/main.js — W6: entry point (init, wire, start) — jogo completo
import C from './constants.js';
import { createEngine } from './engine.js';
import { buildLevel, cellAt } from './map.js';
import { Input } from './input.js';
import { PlayerEntity } from './player.js';
import { WeaponSystem } from './weapons.js';
import { spawnEnemies } from './enemies.js';
import { ParticleSystem } from './particles.js';
import { AudioEngine } from './audio.js';
import { buildMinimapData, renderMinimap } from './minimap.js';
import { buildHudData, renderHud } from './hud.js';
import { Game, STATES } from './game.js';
import { buildWorld } from './world.js';

// WHY: monta o mundo do jogo (tudo que não depende do loop)
const init = () => {
  const canvas = document.getElementById('game');
  const engine = createEngine(canvas);
  engine.resize();
  const level = buildLevel();
  const input = new Input(canvas);
  const audio = new AudioEngine();
  const player = new PlayerEntity(level, input, new WeaponSystem());
  const enemies = spawnEnemies(level, 'imp', 6);
  const particles = new ParticleSystem();
  const hudCtx = document.getElementById('hud').getContext('2d');
  const mapCtx = document.getElementById('minimap').getContext('2d');
  return { engine, level, input, audio, player, enemies, particles, hudCtx, mapCtx, score: 0 };
};

// WHY: tela de menu/fim — texto central no canvas do HUD
const drawOverlay = (ctx, w, h, title, sub) => {
  ctx.fillStyle = 'rgba(0,0,0,0.72)';
  ctx.fillRect(0, 0, w, h);
  ctx.fillStyle = '#ffcc33';
  ctx.font = 'bold 28px monospace';
  ctx.textAlign = 'center';
  ctx.fillText(title, w / 2, h / 2 - 10);
  ctx.fillStyle = '#fff';
  ctx.font = '14px monospace';
  ctx.fillText(sub, w / 2, h / 2 + 20);
};

// WHY: liga update/render/estados ao loop fixed-step do Game
const wire = (w) => {
  buildWorld(w.engine.world, w.level.grid);
  const { camera, renderer, scene } = w.engine;
  let lastHp = w.player.hp;

  const update = (dt) => {
    if (w.game.state !== STATES.PLAYING) return;
    w.player.update(dt);
    // WHY: inimigos atacam — dano aplicado direto (projéteis visuais = W7)
    for (const e of w.enemies) {
      const evt = e.update(dt, w.player, w.level.grid);
      if (evt && evt.damage && evt.damage > 0) w.player.damage(evt.damage);
      if (e.dead) w.score += 10;
    }
    w.particles.update(dt);
    if (w.player.hp < lastHp) w.audio.play('damage');
    lastHp = w.player.hp;
    // WHY: condições de fim — morte (lava/inimigos) ou saída (exit)
    if (w.player.hp <= 0) { w.game.gameOver(); w.audio.play('explosion'); return; }
    const tile = cellAt(w.level.grid, Math.floor(w.player.pos.x), Math.floor(w.player.pos.z));
    if (tile === C.TILES.EXIT) { w.game.win(); w.audio.play('pickup'); }
  };

  const render = () => {
    const hw = w.hudCtx.canvas.width;
    const hh = w.hudCtx.canvas.height;
    const st = w.game.state;
    if (st === STATES.MENU) { drawOverlay(w.hudCtx, hw, hh, 'DOOM CLONE', 'clique para jogar'); return; }
    if (st === STATES.GAMEOVER) { drawOverlay(w.hudCtx, hw, hh, 'VOCÊ MORREU', 'clique para tentar de novo'); return; }
    if (st === STATES.WIN) { drawOverlay(w.hudCtx, hw, hh, 'NÍVEL COMPLETO', `score ${w.score} — clique para jogar`); return; }
    if (st === STATES.PAUSED) { drawOverlay(w.hudCtx, hw, hh, 'PAUSA', 'P para continuar'); return; }
    // WHY: câmera FPS — posição + bob de caminhada + yaw/pitch do input
    camera.position.set(w.player.pos.x, w.player.viewY(), w.player.pos.z);
    camera.rotation.order = 'YXZ';
    camera.rotation.y = -w.player.yaw;
    camera.rotation.x = w.player.pitch;
    renderer.render(scene, camera);
    // WHY: HUD retro + minimap (overlays 2D)
    renderHud(w.hudCtx, buildHudData({ ...w.player, score: w.score }, w.player.weapons), hw, hh);
    renderMinimap(w.mapCtx, buildMinimapData(w.level, w.player, w.enemies, w.level.pickups), 6);
  };

  w.game = new Game({ update, render });
  w.audio.ensureCtx(); // autoplay policy: contexto criado no gesto do usuário
  document.getElementById('game').addEventListener('click', () => {
    if (w.game.state === STATES.MENU || w.game.state === STATES.GAMEOVER || w.game.state === STATES.WIN) {
      w.player.start();
      w.game.startGame();
    }
  });
  window.addEventListener('keydown', (e) => {
    if (e.code === 'KeyP') w.game.togglePause();
  });

  w.game.start();
  return w;
};

// WHY: bootstrap no browser (ES module)
if (typeof window !== 'undefined') {
  window.addEventListener('DOMContentLoaded', () => wire(init()));
}

