import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Game, STATES, FIXED_DT } from '../js/game.js';

// WHY: stub de rAF — captura o callback agendado (browser real = requestAnimationFrame)
const makeFrameStub = () => {
  const stub = { cb: null, calls: 0 };
  stub.requestFrame = (cb) => { stub.cb = cb; stub.calls += 1; };
  return stub;
};

test('estado inicial é MENU e não roda', () => {
  const g = new Game({ update() {}, render() {} });
  assert.equal(g.state, STATES.MENU);
  assert.equal(g.running, false);
});

test('start agenda o loop via requestFrame injetável', () => {
  const stub = makeFrameStub();
  const g = new Game({ update() {}, render() {} }, { requestFrame: stub.requestFrame });
  // nota: constructor recebe ({update, render, requestFrame}) — usar forma correta abaixo
});

test('fixed-step: 100ms acumula 6 passos de 1/60', () => {
  const updates = [];
  const g = new Game({ update: (dt) => updates.push(dt), render() {} });
  g.start();
  g.step(0);
  g.step(100);
  assert.equal(updates.length, 6);
  for (const dt of updates) assert.ok(Math.abs(dt - FIXED_DT) < 1e-9);
  assert.equal(g.frame, 6);
  assert.ok(Math.abs(g.time - 0.1) < 1e-9);
  assert.ok(Math.abs(g.acc - (0.1 - 6 * FIXED_DT)) < 1e-9);
  g.stop();
});

test('clamp: dt de 1s vira no máximo 0.25s (15 passos)', () => {
  let n = 0;
  const g = new Game({ update() { n += 1; }, render() {} });
  g.start();
  g.step(0);
  g.step(1000);
  assert.equal(n, 15);
  g.stop();
});

test('step sem running não atualiza', () => {
  let n = 0;
  const g = new Game({ update() { n += 1; }, render() {} });
  g.step(100);
  assert.equal(n, 0);
});

test('render é chamado 1x por step (após os updates)', () => {
  let renders = 0;
  const g = new Game({ update() {}, render() { renders += 1; } });
  g.start();
  g.step(0);
  g.step(40);
  assert.equal(renders, 2);
  g.stop();
});

test('transições de estado: menu→play→pause→resume→gameover/win', () => {
  const g = new Game({ update() {}, render() {} });
  g.startGame();
  assert.equal(g.state, STATES.PLAYING);
  g.pause();
  assert.equal(g.state, STATES.PAUSED);
  g.pause(); // pause em PAUSED não muda
  assert.equal(g.state, STATES.PAUSED);
  g.resume();
  assert.equal(g.state, STATES.PLAYING);
  g.togglePause();
  assert.equal(g.state, STATES.PAUSED);
  g.togglePause();
  assert.equal(g.state, STATES.PLAYING);
  g.gameOver();
  assert.equal(g.state, STATES.GAMEOVER);
  // resume não volta de GAMEOVER
  g.resume();
  assert.equal(g.state, STATES.GAMEOVER);
});

test('win e gameOver são terminais via togglePause', () => {
  const g = new Game({ update() {}, render() {} });
  g.startGame();
  g.win();
  assert.equal(g.state, STATES.WIN);
  g.togglePause();
  assert.equal(g.state, STATES.WIN);
});

