import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buildHudData, renderHud, COLORS, WEAPON_NAMES } from '../js/hud.js';

// WHY: ctx falso registra chamadas (sem depender de canvas em node)
const makeCtx = () => {
  const calls = [];
  return {
    calls,
    fillStyle: '', strokeStyle: '', font: '', textAlign: '',
    fillRect(...a) { calls.push(['fillRect', ...a]); },
    fillText(...a) { calls.push(['fillText', ...a]); },
    beginPath() { calls.push(['beginPath']); },
    moveTo(...a) { calls.push(['moveTo', ...a]); },
    lineTo(...a) { calls.push(['lineTo', ...a]); },
    stroke() { calls.push(['stroke']); },
  };
};

test('buildHudData extrai hp/armor/ammo/score do player+weapons', () => {
  const player = { hp: 80, maxHp: 100, armor: 20, maxArmor: 100, score: 50 };
  const weapons = { current: 'shotgun', ammo: { shotgun: 8 } };
  assert.deepEqual(buildHudData(player, weapons), {
    hp: 80, maxHp: 100, armor: 20, maxArmor: 100, weapon: 'shotgun', ammo: 8, score: 50,
  });
});

test('buildHudData clampa hp/armor negativos a 0 e arredonda', () => {
  const player = { hp: -5, armor: 87.4, score: 0 };
  const weapons = { current: 'pistol', ammo: { pistol: 50 } };
  const data = buildHudData(player, weapons);
  assert.equal(data.hp, 0);
  assert.equal(data.armor, 87);
});

test('buildHudData usa default maxHp/maxArmor quando ausentes', () => {
  const player = { hp: 100, armor: 0 };
  const weapons = { current: 'fist', ammo: { fist: Infinity } };
  const data = buildHudData(player, weapons);
  assert.equal(data.maxHp, 100);
  assert.equal(data.maxArmor, 100);
  assert.equal(data.weapon, 'fist');
  assert.equal(data.ammo, Infinity);
});

test('WEAPON_NAMES cobre as 4 armas', () => {
  assert.equal(WEAPON_NAMES.fist, 'FIST');
  assert.equal(WEAPON_NAMES.pistol, 'PISTOL');
  assert.equal(WEAPON_NAMES.shotgun, 'SHOTGUN');
  assert.equal(WEAPON_NAMES.rocket, 'ROCKET');
});

test('renderHud: barras proporcionais + ammo + score + crosshair', () => {
  const ctx = makeCtx();
  const data = { hp: 50, maxHp: 100, armor: 25, maxArmor: 100, weapon: 'shotgun', ammo: 8, score: 30 };
  renderHud(ctx, data, 800, 600);

  const fillRects = ctx.calls.filter((c) => c[0] === 'fillRect');
  // painel de fundo + 2 fundos de barra + 2 preenchimentos
  assert.equal(fillRects.length, 5);
  // preenchimento HP = 132 * (50/100) = 66
  const hpFill = fillRects.find((c) => c[3] === 66 && c[2] === 600 - 21);
  assert.ok(hpFill, 'barra HP preenchida com 66px');
  // preenchimento armor = 132 * (25/100) = 33
  const armorFill = fillRects.find((c) => c[3] === 33 && c[2] === 600 - 10);
  assert.ok(armorFill, 'barra armor preenchida com 33px');

  const texts = ctx.calls.filter((c) => c[0] === 'fillText');
  const ammoText = texts.find((t) => String(t[1]).includes('SHOTGUN 8'));
  assert.ok(ammoText, 'texto de ammo com nome e quantidade');
  const scoreText = texts.find((t) => String(t[1]).includes('SCORE 30'));
  assert.ok(scoreText, 'texto de score');

  // crosshair: 1 stroke com 2 moveTo + 2 lineTo
  const strokes = ctx.calls.filter((c) => c[0] === 'stroke');
  const moveTos = ctx.calls.filter((c) => c[0] === 'moveTo');
  const lineTos = ctx.calls.filter((c) => c[0] === 'lineTo');
  assert.equal(strokes.length, 1);
  assert.equal(moveTos.length, 2);
  assert.equal(lineTos.length, 2);
});

test('renderHud: cores das barras (verde HP, azul armor, amarelo ammo)', () => {
  const ctx = makeCtx();
  const data = { hp: 100, maxHp: 100, armor: 100, maxArmor: 100, weapon: 'pistol', ammo: 50, score: 0 };
  renderHud(ctx, data, 400, 300);
  const fillRects = ctx.calls.filter((c) => c[0] === 'fillRect');
  // o fillStyle vigente no momento do fillRect de preenchimento
  const fills = [];
  for (const c of ctx.calls) {
    if (c[0] === 'fillRect') fills.push(ctx.calls.indexOf(c));
  }
  // verificar via sequência: seta fillStyle antes de cada fillRect de preenchimento
  const seq = [];
  for (const c of ctx.calls) {
    if (c[0] === 'fillRect') seq.push(`rect:${ctx.fillStyle}`); // valor registrado fora de ordem
  }
  // abordagem simples: o último fillRect de preenchimento (armor) usa o fillStyle armazenado na hora
  // como o mock guarda só o valor corrente, capturamos por ordem dos sets
  const styleLog = [];
  let current = '';
  for (const c of ctx.calls) {
    if (c[0] === 'fillRect') { styleLog.push(current); continue; }
    if (typeof c[1] === 'string' && c[1].startsWith('#')) current = c[1];
  }
  // 5 rects: painel(bg rgba), fundo hp(#111), preench hp(#33ff33), fundo armor(#111), preench armor(#3366ff)
  assert.equal(styleLog[2], COLORS.hp);
  assert.equal(styleLog[4], COLORS.armor);
});

