// Validação CDP do DOOM clone — preview (refatorado) + index.html (main.js novo)
// Uso: node /tmp/opencode/validate.js
const BASE = 'http://127.0.0.1:3001';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function cdp(wsUrl) {
  const ws = new WebSocket(wsUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
  let id = 0;
  const pending = new Map();
  const events = [];
  ws.onmessage = (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
    else if (msg.method) events.push(msg);
  };
  const send = (method, params = {}) => new Promise((res) => {
    const mid = ++id;
    pending.set(mid, res);
    ws.send(JSON.stringify({ id: mid, method, params }));
  });
  const waitEvent = (method, timeout = 15000) => new Promise((res, rej) => {
    const t0 = Date.now();
    const iv = setInterval(() => {
      const i = events.findIndex((e) => e.method === method);
      if (i >= 0) { clearInterval(iv); res(events.splice(i, 1)[0]); }
      else if (Date.now() - t0 > timeout) { clearInterval(iv); rej(new Error('timeout ' + method)); }
    }, 25);
  });
  return { ws, send, waitEvent, events };
}

async function evalJs(c, expr) {
  const r = await c.send('Runtime.evaluate', { expression: expr, returnByValue: true });
  return r.result?.result?.value;
}

async function checkPage(c, url, checks, opts = {}) {
  const consoleErrors = [];
  const seen = new Set();
  const onEvt = (ev) => {
    if (ev.method === 'Runtime.exceptionThrown') consoleErrors.push(JSON.stringify(ev.params.exceptionDetails).slice(0, 300));
    if (ev.method === 'Log.entryAdded' && ev.params.entry.level === 'error') consoleErrors.push(ev.params.entry.text.slice(0, 300));
    if (ev.method === 'Runtime.consoleAPICalled' && ev.params.type === 'error') {
      const txt = ev.params.args.map((a) => a.value ?? a.description ?? '').join(' ');
      if (!seen.has(txt)) { seen.add(txt); consoleErrors.push(txt.slice(0, 300)); }
    }
  };
  const orig = c.events.push.bind(c.events);
  c.events.push = (m) => { onEvt(m); return orig(m); };

  await c.send('Page.navigate', { url });
  await c.waitEvent('Page.loadEventFired');
  await sleep(opts.settle ?? 1500);

  const out = {};
  for (const [k, expr] of Object.entries(checks)) out[k] = await evalJs(c, expr);
  out.consoleErrors = consoleErrors;
  return out;
}

async function main() {
  const { version } = await (await fetch('http://127.0.0.1:9222/json/version')).json();
  console.log('CDP', version.Browser);
  const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
  const page = targets.find((t) => t.type === 'page');
  const c = await cdp(page.webSocketDebuggerUrl);
  await c.send('Page.enable');
  await c.send('Runtime.enable');
  await c.send('Log.enable');

  // ---- PREVIEW (refatorado: usa world.js) ----
  console.log('\n=== PREVIEW preview.html ===');
  const pv = await checkPage(c, BASE + '/preview.html', {
    canvasW: "document.getElementById('game').width",
    canvasH: "document.getElementById('game').height",
    ready: 'document.readyState',
    webgl: "(document.getElementById('game').getContext('webgl') !== null)",
  });
  // loop vivo: rAF conta nos próximos 500ms
  await evalJs(c, "window.__raf = 0; (function(){const o=requestAnimationFrame;requestAnimationFrame=function(f){window.__raf++;return o(f);};})();");
  await sleep(600);
  const raf = await evalJs(c, 'window.__raf');
  console.log('canvas', pv.canvasW + 'x' + pv.canvasH, '| ready', pv.ready, '| webgl', pv.webgl, '| rAF(600ms)', raf);
  console.log('erros:', pv.consoleErrors.length ? pv.consoleErrors : 'nenhum');

  // ---- INDEX (main.js novo: MENU -> click -> PLAYING) ----
  console.log('\n=== INDEX index.html ===');
  const idx = await checkPage(c, BASE + '/index.html', {
    canvases: "[...document.querySelectorAll('canvas')].map(c=>c.id).join(',')",
    hudPixels: "(function(){const c=document.getElementById('hud');const d=c.getContext('2d');const img=d.getImageData(0,0,c.width,c.height).data;let n=0;for(let i=3;i<img.length;i+=4)if(img[i]>0)n++;return n;})()",
    minimapPixels: "(function(){const c=document.getElementById('minimap');const d=c.getContext('2d');const img=d.getImageData(0,0,c.width,c.height).data;let n=0;for(let i=3;i<img.length;i+=4)if(img[i]>0)n++;return n;})()",
    gameDims: "[document.getElementById('game').width,document.getElementById('game').height].join('x')",
  });
  console.log('canvases:', idx.canvases, '| game:', idx.gameDims);
  console.log('hud pixels (MENU overlay):', idx.hudPixels, '| minimap pixels:', idx.minimapPixels);
  console.log('erros:', idx.consoleErrors.length ? idx.consoleErrors : 'nenhum');

  // clique para começar
  await c.send('Input.dispatchMouseEvent', { type: 'mousePressed', x: 400, y: 300, button: 'left', clickCount: 1 });
  await c.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: 400, y: 300, button: 'left', clickCount: 1 });
  await sleep(800);
  const play = await evalJs(c, "(function(){const c=document.getElementById('hud');const d=c.getContext('2d');const img=d.getImageData(0,0,c.width,c.height).data;let green=0,blue=0;for(let i=0;i<img.length;i+=4){if(img[i]>150&&img[i+1]>150&&img[i+2]<100)green++;if(img[i+2]>150&&img[i+1]>80&&img[i]<100)blue++;}return {green,blue};})()");
  console.log('após click — pixels verdes(HP):', play.green, 'azuis(armor):', play.blue);
  const shot = await c.send('Page.captureScreenshot', { format: 'png' });
  require('fs').writeFileSync('/tmp/opencode/w6-play.png', Buffer.from(shot.result.data, 'base64'));
  console.log('screenshot: /tmp/opencode/w6-play.png');

  // pause via P
  await c.send('Input.dispatchKeyEvent', { type: 'keyDown', code: 'KeyP', key: 'p' });
  await c.send('Input.dispatchKeyEvent', { type: 'keyUp', code: 'KeyP', key: 'p' });
  await sleep(300);
  const paused = await evalJs(c, "(function(){const c=document.getElementById('hud');const d=c.getContext('2d');const img=d.getImageData(0,0,c.width,c.height).data;let dark=0,total=0;for(let i=3;i<img.length;i+=4){total++;if(img[i]>180)dark++;}return {dark,total};})()");
  console.log('após P — pixels alpha>180:', paused.dark, '/', paused.total);

  c.ws.close();
  process.exit(0);
}

main().catch((e) => { console.error('FALHA:', e.message); process.exit(1); });

