// tests/integration.test.mjs — W7: fluxos completos com módulos reais
// play (movimento + win), shoot (4 armas), enemy attack (+LOS), pickup (H/A/W), exit, gameover
import { test } from 'node:test';
import assert from 'node:assert/strict';
import C from '../js/constants.js';
import { buildLevel, cellAt } from '../js/map.js';
import { PlayerEntity } from '../js/player.js';
import { WeaponSystem } from '../js/weapons.js';
import { spawnEnemies } from '../js/enemies.js';
import { Game, STATES } from '../js/game.js';

// WHY: input stub determinístico (browser não existe em node)
const makeInput = (over = {}) => ({
  getAxis: () => over.axis ?? { x: 0, z: 0 },
  yaw: over.yaw ?? 0,
  pitch: 0,
  isDown: () => false,
  ...over,
});

// WHY: replica o update do main.js (player + enemies + win/gameover) — teste do fluxo real
const wireMiniMain = (player, enemies, level) => {
  const game = new Game({
    update(dt) {
      player.update(dt);
      for (const e of enemies) {
        const evt = e.update(dt, player, level.grid);
        if (evt && evt.damage && evt.damage > 0) player.damage(evt.damage);
      }
      if (player.hp <= 0) { game.gameOver(); return; }
      const tile = cellAt(level.grid, Math.floor(player.pos.x), Math.floor(player.pos.z));
      if (tile === C.TILES.EXIT) game.win();
    },
    render() {},
  });
  return game;
};

test('play: MENU→start→PLAYING e update move o player na direção do yaw', () => {
  const level = buildLevel();
  const player = new PlayerEntity(level, makeInput({ axis: { x: 0, z: 1 }, yaw: 0 }), new WeaponSystem());
  const game = wireMiniMain(player, [], level);
  game.start();
  game.step(0);
  game.startGame();
  assert.equal(game.state, STATES.PLAYING);
  const z0 = player.pos.z;
  game.step(17);
  game.step(17);
  assert.ok(player.pos.z > z0, 'player deveria andar em +z com yaw=0');
  game.stop();
});

test('win: player sobre o tile EXIT → estado WIN', () => {
  const level = buildLevel();
  const player = new PlayerEntity(level, makeInput(), new WeaponSystem());
  const game = wireMiniMain(player, [], level);
  game.start();
  game.step(0);
  game.startGame();
  player.pos = { x: 3.5, z: 41.5 }; // FIXED_EXITS (3,41)
  assert.equal(cellAt(level.grid, 3, 41), C.TILES.EXIT);
  game.step(17);
  assert.equal(game.state, STATES.WIN);
  game.stop();
});

test('gameover: hp <= 0 → estado GAMEOVER', () => {
  const level = buildLevel();
  const player = new PlayerEntity(level, makeInput(), new WeaponSystem());
  const game = wireMiniMain(player, [], level);
  game.start();
  game.step(0);
  game.startGame();
  player.damage(1000);
  assert.equal(player.hp, 0);
  game.step(17);
  assert.equal(game.state, STATES.GAMEOVER);
  game.stop();
});

test('shoot: pistol hitscan gasta munição e respeita cooldown', () => {
  const level = buildLevel();
  const weapons = new WeaponSystem();
  const player = new PlayerEntity(level, makeInput(), weapons);
  player.start();
  const before = weapons.ammo.pistol;
  const shot = weapons.fire(player, level.grid);
  assert.equal(shot.type, 'hitscan');
  assert.equal(shot.weapon, 'pistol');
  assert.ok(shot.damage > 0);
  assert.equal(weapons.ammo.pistol, before - C.WEAPON.pistol.ammoCost);
  // cooldown impede tiro imediato
  assert.equal(weapons.canFire(), false);
  assert.equal(weapons.fire(player, level.grid), null);
  // após rate segundos, pode atirar de novo
  weapons.update(C.WEAPON.pistol.rate + 0.01);
  assert.equal(weapons.canFire(), true);
});

test('shoot: shotgun spread dispara pellets; fist melee não gasta munição', () => {
  const level = buildLevel();
  const weapons = new WeaponSystem();
  const player = new PlayerEntity(level, makeInput(), weapons);
  player.start();
  weapons.switchWeapon(2); // shotgun
  const shot = weapons.fire(player, level.grid);
  assert.equal(shot.type, 'spread');
  assert.equal(shot.pellets.length, C.WEAPON.shotgun.pellets);
  assert.equal(weapons.ammo.shotgun, 12 - C.WEAPON.shotgun.ammoCost);
  weapons.switchWeapon(0); // fist
  const melee = weapons.fire(player, level.grid);
  assert.equal(melee.type, 'melee');
  assert.equal(weapons.ammo.fist, Infinity, 'fist não gasta munição');
});

test('shoot: rocket projectile tem proj com direção e velocidade', () => {
  const level = buildLevel();
  const weapons = new WeaponSystem();
  const player = new PlayerEntity(level, makeInput({ yaw: 0 }), weapons);
  player.start();
  weapons.switchWeapon(3); // rocket
  const shot = weapons.fire(player, level.grid);
  assert.equal(shot.type, 'projectile');
  assert.ok(shot.proj.speed > 0);
  assert.equal(shot.proj.dx, Math.sin(0));
  assert.equal(shot.proj.dz, Math.cos(0));
});

test('enemy attack: imp próximo fere o player (via evt do update)', () => {
  const level = buildLevel();
  const player = new PlayerEntity(level, makeInput(), new WeaponSystem());
  player.start();
  player.pos = { x: 17.5, z: 23.0 }; // 1.5 tile do spawn de inimigos (17.5, 24.5)
  const enemies = spawnEnemies(level, 'imp', 1);
  assert.equal(enemies.length, 1);
  const hp0 = player.hp;
  let evt = null;
  for (let i = 0; i < 10 && !evt; i++) {
    for (const e of enemies) {
      const r = e.update(1 / 60, player, level.grid);
      if (r && r.damage > 0) evt = r;
    }
  }
  assert.ok(evt, 'imp deveria atacar dentro de 10 updates');
  player.damage(evt.damage);
  assert.ok(player.hp < hp0, 'player deveria perder hp');
});

test('enemy attack: sem LOS (parede entre) → imp permanece idle e não ataca', () => {
  const level = buildLevel();
  const player = new PlayerEntity(level, makeInput(), new WeaponSystem());
  player.start();
  player.pos = { x: 5.5, z: 24.5 }; // atrás da parede da coluna 8 (linha 24)
  const enemies = spawnEnemies(level, 'imp', 1);
  const imp = enemies[0];
  let evt = null;
  for (let i = 0; i < 10; i++) {
    for (const e of enemies) {
      const r = e.update(1 / 60, player, level.grid);
      if (r && r.damage > 0) evt = r;
    }
  }
  assert.equal(evt, null, 'sem LOS não deve haver ataque');
  assert.equal(imp.state, 'idle');
});

test('pickup: H restaura hp (cap 100) e remove da lista', () => {
  const level = buildLevel();
  const player = new PlayerEntity(level, makeInput(), new WeaponSystem());
  player.start();
  player.damage(40);
  assert.equal(player.hp, 60);
  const n0 = level.pickups.length;
  player.pos = { x: 2.5, z: 4.5 }; // FIXED_PICKUPS H (2,4)
  player.update(1 / 60);
  assert.equal(player.hp, 85, 'H deve restaurar 25 hp');
  assert.equal(level.pickups.length, n0 - 1, 'pickup coletado sai da lista');
});

test('pickup: A dá armor (cap 100); W dá munição para todas (cap maxAmmo)', () => {
  const level = buildLevel();
  const weapons = new WeaponSystem();
  const player = new PlayerEntity(level, makeInput(), weapons);
  player.start();
  player.pos = { x: 9.5, z: 2.5 }; // FIXED_PICKUPS A (9,2)
  player.update(1 / 60);
  assert.equal(player.armor, 25);
  player.pos = { x: 15.5, z: 2.5 }; // FIXED_PICKUPS W (15,2)
  player.update(1 / 60);
  assert.equal(weapons.ammo.pistol, Math.min(C.WEAPON.pistol.maxAmmo, 50 + 20));
  assert.equal(weapons.ammo.shotgun, Math.min(C.WEAPON.shotgun.maxAmmo, 12 + 20));
  assert.equal(weapons.ammo.rocket, Math.min(C.WEAPON.rocket.maxAmmo, 4 + 20));
});

test('pickup: lava causa dano contínuo (hazard)', () => {
  const level = buildLevel();
  const player = new PlayerEntity(level, makeInput(), new WeaponSystem());
  player.start();
  const hp0 = player.hp;
  player.pos = { x: 11.5, z: 19.5 }; // FIXED_LAVA (11,19)
  player.update(1 / 60);
  assert.ok(player.hp < hp0, 'lava deve causar dano');
});

test('enemy death: dano suficiente → dead + estado death', () => {
  const level = buildLevel();
  const player = new PlayerEntity(level, makeInput(), new WeaponSystem());
  const enemies = spawnEnemies(level, 'imp', 1);
  const imp = enemies[0];
  imp.damage(C.ENEMY.imp.hp + 1);
  assert.equal(imp.dead, true);
  assert.equal(imp.state, 'death');
  assert.equal(imp.update(1 / 60, player, level.grid), null, 'morto não age');
});

