import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';

const COV = 'coverage/coverage-final.json';

// WHY: c8 v12 não expõe lines.covered — calcula linhas a partir do statementMap
const coveredLines = (f) => new Set(
  Object.entries(f.s).filter(([, c]) => c > 0).map(([id]) => f.statementMap[id].start.line),
).size;
const totalLines = (f) => new Set(Object.values(f.statementMap).map((s) => s.start.line)).size;
const covered = (f, map) => Object.values(f[map]).filter((c) => c > 0).length;
const total = (f, map) => Object.keys(f[map]).length;

test('cobertura total > 80% (c8)', {
  skip: !existsSync(COV) && 'sem relatório — rode: npx c8 --reporter=lcov --reporter=json node --test "tests/*.test.mjs"',
}, () => {
  const files = Object.values(JSON.parse(readFileSync(COV, 'utf8')));
  const sum = (get) => files.reduce((a, f) => a + get(f), 0);
  const pct = (cov, tot) => (cov / tot) * 100;

  const linesPct = pct(sum(coveredLines), sum(totalLines));
  const stmtsPct = pct(sum((f) => covered(f, 's')), sum((f) => total(f, 's')));
  const funcsPct = pct(sum((f) => covered(f, 'f')), sum((f) => total(f, 'f')));

  assert.ok(linesPct > 80, `linhas cobertas: ${linesPct.toFixed(1)}% (exigido >80%)`);
  assert.ok(stmtsPct > 80, `statements cobertos: ${stmtsPct.toFixed(1)}%`);
  assert.ok(funcsPct > 80, `funções cobertas: ${funcsPct.toFixed(1)}%`);
});

