/* W8: scanlines + vignette CRT; overlays/HUD desenhados no canvas #hud */
:root {
  --bg: #1a1a1a;
  --border: #aa2222;
  --text: #cccccc;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: "Courier New", monospace;
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
}

#game {
  display: block;
  width: 100%;
  height: 100%;
  cursor: none;
  position: relative;
}

/* Scanlines CRT (2px) sobre a cena */
#game::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    rgba(0, 0, 0, 0.12),
    rgba(0, 0, 0, 0.12) 1px,
    transparent 1px,
    transparent 2px
  );
  pointer-events: none;
  z-index: 10;
}

/* Vignette CRT (escuridão nas bordas) */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  background: radial-gradient(ellipse at center, transparent 55%, rgba(0, 0, 0, 0.4) 100%);
  pointer-events: none;
  z-index: 9;
}

/* HUD — canvas overlay (W6: painel desenhado no canvas, retro) */
#hud {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 5;
}

/* Prévia — ajuda e posição */
#help {
  font-size: 13px;
  color: var(--text);
  white-space: nowrap;
}

#pos {
  font-size: 13px;
  color: #aacccc;
  white-space: nowrap;
}

