// tests/e2e/doom.spec.mjs — W8: E2E no browser real (chromium via playwright-core)
// R29: teste como usuário final — cliques, teclado, estado real via hook window.__doom
import { test, expect } from '@playwright/test';

// WHY: hook do main.js expõe o estado para leitura/teleporte determinístico
const boot = async (page) => {
  await page.goto('/');
  await page.waitForFunction(() => window.__doom !== undefined);
  return page.evaluate(() => window.__doom);
};

const state = (page) => page.evaluate(() => window.__doom.game.state);

test('fluxo: MENU→PLAYING→PAUSED→PLAYING→WIN→reinicia→GAMEOVER→reinicia', async ({ page }) => {
  await boot(page);
  expect(await state(page)).toBe('MENU');
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
  await page.keyboard.press('KeyP');
  await page.waitForFunction(() => window.__doom.game.state === 'PAUSED');
  await page.keyboard.press('KeyP');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
  // WIN: teleporta para o exit fixo (3,41) — fluxo real do update (cellAt EXIT → win)
  await page.evaluate(() => { window.__doom.player.pos = { x: 3.5, z: 41.5 }; });
  await page.waitForFunction(() => window.__doom.game.state === 'WIN');
  // clique reinicia partida
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
  // GAMEOVER: dano letal → fluxo real do update (hp<=0 → gameOver)
  await page.evaluate(() => window.__doom.player.damage(1000));
  await page.waitForFunction(() => window.__doom.game.state === 'GAMEOVER');
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
});

test('tiro: mousedown dispara (pistol/shotgun) e fist não gasta munição', async ({ page }) => {
  await boot(page);
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
  // pistol (slot 2 = Digit2, inventory index 1)
  await page.keyboard.press('Digit2');
  await page.waitForFunction(() => window.__doom.player.weapons.current === 1);
  expect(await page.evaluate(() => window.__doom.player.weapons.ammo.pistol)).toBe(50);
  await page.mouse.click(400, 300);
  await page.waitForFunction(() => window.__doom.player.weapons.ammo.pistol === 49);
  // shotgun (Digit3, index 2)
  await page.keyboard.press('Digit3');
  await page.waitForFunction(() => window.__doom.player.weapons.current === 2);
  await page.mouse.click(400, 300);
  await page.waitForFunction(() => window.__doom.player.weapons.ammo.shotgun === 11);
  // fist (Digit1, index 0) — munição infinita não muda
  await page.keyboard.press('Digit1');
  await page.waitForFunction(() => window.__doom.player.weapons.current === 0);
  await page.mouse.click(400, 300);
  expect(await page.evaluate(() => window.__doom.player.weapons.ammo.fist)).toBe(Infinity);
});

test('pickups: H restaura hp, A dá armor, W dá munição (cap maxAmmo)', async ({ page }) => {
  await boot(page);
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
  await page.evaluate(() => window.__doom.player.damage(40));
  await page.waitForFunction(() => window.__doom.player.hp === 60);
  // HEALTH (2,4): +25 hp → 85
  await page.evaluate(() => { window.__doom.player.pos = { x: 2.5, z: 4.5 }; });
  await page.waitForFunction(() => window.__doom.player.hp === 85);
  // ARMOR (9,2): +25 armor
  await page.evaluate(() => { window.__doom.player.pos = { x: 9.5, z: 2.5 }; });
  await page.waitForFunction(() => window.__doom.player.armor === 25);
  // WEAPON (15,2): +20 para todas as armas (cap maxAmmo)
  await page.evaluate(() => { window.__doom.player.pos = { x: 15.5, z: 2.5 }; });
  await page.waitForFunction(() => window.__doom.player.weapons.ammo.pistol === 70);
  expect(await page.evaluate(() => window.__doom.player.weapons.ammo.shotgun)).toBe(32);
  expect(await page.evaluate(() => window.__doom.player.weapons.ammo.rocket)).toBe(24);
});

test('minimap: paredes/lava/exit/inimigos/pickups visíveis + screenshot', async ({ page }) => {
  await boot(page);
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
  await page.waitForTimeout(200); // garante render do minimap
  const colors = await page.evaluate(() => {
    const w = window.__doom;
    const d = w.mapCtx.getImageData(0, 0, w.mapCtx.canvas.width, w.mapCtx.canvas.height).data;
    const count = (hex) => {
      const r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);
      let n = 0;
      for (let i = 0; i < d.length; i += 4) if (d[i] === r && d[i + 1] === g && d[i + 2] === b) n++;
      return n;
    };
    return { walls: count('#888888'), lava: count('#ff4422'), exit: count('#33ff66'), enemies: count('#ff3333'), pickups: count('#33ccff') };
  });
  expect(colors.walls).toBeGreaterThan(100);
  expect(colors.lava).toBeGreaterThan(0);
  expect(colors.exit).toBeGreaterThan(0);
  expect(colors.enemies).toBeGreaterThan(0);
  expect(colors.pickups).toBeGreaterThan(0);
  await page.locator('#minimap').screenshot({ path: '/tmp/opencode/w8-minimap.png' });
});

test('HUD: barra HP verde, armor azul, crosshair presente + screenshot', async ({ page }) => {
  await boot(page);
  await page.click('#game');
