// diag2 — Group breakdown + grid à frente da câmera + iluminação efetiva
import { chromium } from 'playwright-core';

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  args: ['--enable-unsafe-swiftshader', '--no-sandbox'],
});
const page = await browser.newPage();
await page.goto('http://127.0.0.1:3001');
await page.waitForFunction(() => window.__doom !== undefined);
await page.click('#game');
await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
await page.waitForTimeout(600);

const info = await page.evaluate(() => {
  const w = window.__doom;
  const { world } = w.engine;
  const counts = {};
  for (const c of world.children) {
    const key = c.isMesh ? 'mesh:' + c.material.type : c.type;
    counts[key] = (counts[key] ?? 0) + 1;
  }
  const g = w.level.grid;
  const north = [], south = [];
  for (let z = 22; z >= 0; z--) north.push(`${z}:${g[z][18]}`);
  for (let z = 22; z <= 43; z++) south.push(`${z}:${g[z][18]}`);
  return {
    worldChildren: world.children.length,
    counts,
    spawnTile: g[22][18],
    north: north.join(' '),
    south: south.join(' '),
    bg: w.engine.scene.background ? w.engine.scene.background.getHexString() : null,
    fog: [w.engine.scene.fog?.near, w.engine.scene.fog?.far],
  };
});
console.log(JSON.stringify(info, null, 2));
await browser.close();

