const info = await page.evaluate(() => new Promise((resolve) => {
  requestAnimationFrame(() => {
    const w = window.__doom;
    const { renderer, scene, camera } = w.engine;
    renderer.render(scene, camera); // força um frame agora
    const gl = document.getElementById('game').getContext('webgl2');
    const px = new Uint8Array(4);
    gl.readPixels(Math.floor(gl.drawingBufferWidth / 2), Math.floor(gl.drawingBufferHeight / 2), 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
    const px2 = new Uint8Array(4);
    gl.readPixels(20, Math.floor(gl.drawingBufferHeight * 0.8), 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px2);
    resolve({
      triangles: renderer.info.render.triangles,
      calls: renderer.info.render.calls,
      centerPixel: [...px],
      upperLeftPixel: [...px2],
      drawingBuffer: [gl.drawingBufferWidth, gl.drawingBufferHeight],
      webgl2: gl instanceof WebGL2RenderingContext,
      camPos: [camera.position.x, camera.position.y, camera.position.z],
      camRot: [camera.rotation.x, camera.rotation.y, camera.rotation.z],
    });
  });
}));
console.log(JSON.stringify(info, null, 2));
await browser.close();

