// WHY: câmera usa rotation.y = -yaw → frente = (sin yaw, -cos yaw); R_y(-yaw).
// (R_y(+yaw) era o bug "teclas WS invertidas" reportado pelo usuário)
test('R_y(-yaw): yaw=PI/2 com wish {0,1} anda em -x', () => {
  const p = new PlayerEntity(level, makeInput({ axis: { x: 0, z: 1 }, yaw: Math.PI / 2 }), weapons);
  p.start();
  const x0 = p.pos.x;
  for (let i = 0; i < 30; i++) p.update(1 / 60);
  assert.ok(p.pos.x < x0, `pos.x deveria decrescer com R_y=- (${x0} -> ${p.pos.x})`);
});

test('R_y(-yaw): yaw=-PI/2 com wish {0,1} anda em +x', () => {
  const p = new PlayerEntity(level, makeInput({ axis: { x: 0, z: 1 }, yaw: -Math.PI / 2 }), weapons);
  p.start();
  const x0 = p.pos.x;
  for (let i = 0; i < 30; i++) p.update(1 / 60);
  assert.ok(p.pos.x > x0, `pos.x deveria crescer (${x0} -> ${p.pos.x})`);
});

