// diag5 — evidência final: #hud transparente em PLAYING + cena visível no buffer
import { chromium } from 'playwright-core';

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  args: ['--enable-unsafe-swiftshader', '--no-sandbox'],
});
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
await page.goto('http://127.0.0.1:3001');
await page.waitForFunction(() => window.__doom !== undefined);
// MENU: #hud deve ter o overlay escuro (alpha > 0 no centro)
const menuAlpha = await page.evaluate(() => {
  const ctx = document.getElementById('hud').getContext('2d');
  const d = ctx.getImageData(640, 300, 1, 1).data;
  return [d[0], d[1], d[2], d[3]];
});
await page.click('#game');
await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
await page.waitForTimeout(800);
// PLAYING: #hud deve estar transparente no centro (alpha 0) e opaco no painel
const info = await page.evaluate(() => new Promise((resolve) => {
  requestAnimationFrame(() => {
    const w = window.__doom;
    w.engine.renderer.render(w.engine.scene, w.engine.camera);
    const hud = document.getElementById('hud').getContext('2d');
    const center = hud.getImageData(640, 300, 1, 1).data;
    const panel = hud.getImageData(640, 710, 1, 1).data;
    const cross = hud.getImageData(640, 360, 1, 1).data;
    const gl = document.getElementById('game').getContext('webgl2');
    const px = new Uint8Array(4);
    gl.readPixels(640, 360, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
    resolve({
      hudCenter: [...center],
      hudPanel: [...panel],
      hudCross: [...cross],
      sceneCenter: [...px],
      triangles: w.engine.renderer.info.render.triangles,
    });
  });
}));
console.log(JSON.stringify({ menuAlpha, ...info }, null, 2));
await page.screenshot({ path: '/tmp/opencode/fix-final.png' });
await browser.close();

