tool_input.newString:
class WeaponSystem {
  constructor() {
    // WHY: inventário começa só com fist+pistol; shotgun/rocket são desbloqueados
    // pelos pickups W (DOOM clássico — antes todas as 4 armas já vinham "equipadas",
    // então "armas não apareciam" e o pickup W só dava munição)
    this.inventory = ['fist', 'pistol'];
    this.current = 0;
    this.ammo = { fist: Infinity, pistol: 50, shotgun: 12, rocket: 4 };
    this.cooldown = 0;
  }

  get weapon() { return C.WEAPON[this.inventory[this.current]]; }
  get name() { return this.weapon.name; }
  get key() { return this.inventory[this.current]; }

  // WHY: desbloqueia arma (pickup W) e equipa automaticamente (DOOM clássico)
  unlockWeapon(key) {
    if (!C.WEAPON[key]) return false;
    if (!this.inventory.includes(key)) {
      this.inventory.push(key);
      this.current = this.inventory.length - 1;
    }
    return true;
  }

  update(dt) {
    this.cooldown = Math.max(0, this.cooldown - dt);
  }

  canFire() {
    const w = this.weapon;
    return this.cooldown <= 0 && (this.key === 'fist' || this.ammo[this.key] >= w.ammoCost);
  }

  // WHY: switch por SLOT fixo (1-4) — arma não-desbloqueada não troca (W9)
  switchWeapon(slot) {
    const key = SLOTS[slot];
    if (key && this.inventory.includes(key)) this.current = this.inventory.indexOf(key);
  }

