// WHY: inimigo mais próximo na linha de tiro (hitscan/spread) — W9: antes o tiro
// só colidia com o grid e nunca acertava inimigos (jogo injogável)
const raycastEnemy = (player, grid, enemies, maxDist, doors = []) => {
  const dirX = Math.sin(player.yaw);
  const dirZ = Math.cos(player.yaw);
  let best = null;
  let bestAlong = Infinity;
  for (const e of enemies) {
    if (e.dead) continue;
    const dx = e.pos.x - player.pos.x;
    const dz = e.pos.z - player.pos.z;
    const along = dx * dirX + dz * dirZ;
    if (along <= 0 || along > maxDist) continue;
    // WHY: distância perpendicular ao raio — acerta se o centro está a < size*0.5 do raio
    const perp = Math.abs(dx * dirZ - dz * dirX);
    if (perp > e.stats.size * 0.5) continue;
    if (!hasLineOfSight(grid, player.pos.x, player.pos.z, e.pos.x, e.pos.z, doors)) continue;
    if (along < bestAlong) { best = e; bestAlong = along; }
  }
  return best;
};

// WHY: inimigo mais próximo dentro do alcance melee
const meleeTarget = (player, enemies, range, doors = []) => {
  let best = null;
  let bestDist = range;
  for (const e of enemies) {
    if (e.dead) continue;
    const d = hypot(e.pos.x - player.pos.x, e.pos.z - player.pos.z);
    if (d <= bestDist && hasLineOfSight(doors.length ? gridOrDoors : undefined, 0, 0, 0, 0, doors)) best = e;
    if (d <= bestDist) { bestDist = d; best = e; }
  }
  return best;
};

export { WeaponSystem, raycast, raycastEnemy };

