describe('combate — raycastEnemy e meleeTarget (W9)', () => {
  // WHY: grids pequenos de string (char '#' = parede) — mesmo padrão do enemies.test
  const grid = ['#####', '#...#', '#...#', '#...#', '#####'].map((r) => r.split(''));
  const block = ['#####', '#.#.#', '#.#.#', '#.#.#', '#####'].map((r) => r.split(''));
  const mkPlayer = (x, z, yaw) => ({ pos: { x, z }, yaw });
  const mkEnemy = (x, z) => ({ pos: { x, z }, dead: false, stats: { size: 0.5 } });

  it('acerta inimigo na linha de tiro com LOS (yaw 0 = -Z)', () => {
    const player = mkPlayer(1.5, 2.5, 0);
    const e = mkEnemy(1.5, 1.5);
    assert.equal(raycastEnemy(player, grid, [e], 5), e);
  });

  it('ignora mortos e alvos fora do alcance ou do raio', () => {
    const player = mkPlayer(1.5, 2.5, 0);
    const dead = mkEnemy(1.5, 1.5);
    dead.dead = true;
    const perp = mkEnemy(2.5, 1.5); // perpendicular 1 > size*0.5
    assert.equal(raycastEnemy(player, grid, [dead, perp], 5), null);
    const far = mkEnemy(1.5, 1.5); // no alcance mas maxDist 0.5
    assert.equal(raycastEnemy(player, grid, [far], 0.5), null);
  });

  it('escolhe o inimigo mais próximo na linha', () => {
    const player = mkPlayer(1.5, 2.5, 0);
    const near = mkEnemy(1.5, 2.0);
    const farE = mkEnemy(1.5, 1.0);
    assert.equal(raycastEnemy(player, grid, [farE, near], 5), near);
  });

  it('parede bloqueia (sem LOS) → null', () => {
    const player = mkPlayer(1.5, 2.5, 0);
    const e = mkEnemy(1.5, 0.5); // parede na célula (1,1) entre eles
    assert.equal(raycastEnemy(player, block, [e], 5), null);
  });

  it('meleeTarget escolhe o inimigo vivo mais próximo no alcance', () => {
    const player = { pos: { x: 1.5, z: 2.5 } };
    const near = mkEnemy(1.6, 2.4);
    const farE = mkEnemy(1.5, 1.5);
    const dead = mkEnemy(1.7, 2.5);
    dead.dead = true;
    assert.equal(meleeTarget(player, [farE, near, dead], 2), near);
    assert.equal(meleeTarget(player, [farE], 0.5), null);
  });
});

