const wire = (w) => {
  buildWorld(w.engine.world, w.level.grid);
  const enemyMeshes = buildEnemyMeshes(w.engine.world, w.enemies);
  const viewmodel = buildViewmodel(w.engine.camera);
  const { camera, renderer, scene } = w.engine;
  let lastHp = w.player.hp;
  w.projectiles = [];

  // WHY: splash do foguete — dano a todos os inimigos na área (não ao player)
  const splashDamage = (x, z, radius, damage) => {
    for (const e of w.enemies) {
      if (e.dead) continue;
      const d = Math.hypot(e.pos.x - x, e.pos.z - z);
      if (d <= radius) e.damage(damage);
    }
  };

  // WHY: projétil do jogo com mesh visível — owner 'enemy' acerta player; 'player' acerta inimigos
  const pushProjectile = (from, dir, speed, damage, owner, splash = 0) => {
    w.projectiles.push({
      x: from.x, z: from.z,
      dir: { x: dir.x, z: dir.z },
      speed, damage, owner, splash,
      mesh: createProjectileMesh(scene, from.x, from.z),
    });
  };

  const update = (dt) => {
    if (w.game.state !== STATES.PLAYING) return;
    w.__updates = (w.__updates ?? 0) + 1; // WHY: contador p/ profiling fixed-step (E2E)
    w.player.update(dt);
    for (const e of w.enemies) {
      const evt = e.update(dt, w.player, w.level.grid);
      // WHY: melee/hitscan = dano direto; projectile/double/arc = projétil visível
      if (evt && evt.damage > 0) {
        if (evt.type === 'melee') {
          w.player.damage(evt.damage);
          knockback(w.player.vel, evt.from.x - w.player.pos.x, evt.from.z - w.player.pos.z, 2.5);
        } else if (evt.type === 'hitscan') {
          w.player.damage(evt.damage);
        } else if (evt.type === 'double') {
          const a = { x: evt.dir.x, z: evt.dir.z };
          const rot = (s) => ({ x: a.x * Math.cos(s) - a.z * Math.sin(s), z: a.x * Math.sin(s) + a.z * Math.cos(s) });
          pushProjectile(evt.from, rot(0.12), evt.speed ?? 6, evt.damage, 'enemy');
          pushProjectile(evt.from, rot(-0.12), evt.speed ?? 6, evt.damage, 'enemy');
        } else {
          pushProjectile(evt.from, evt.dir, evt.speed ?? 6, evt.damage, 'enemy');
        }
      }
      // WHY: score só na transição viva→morta — antes somava +10 todo frame (infinito)
      if (e.dead && !e.scored) { e.scored = true; w.score += 10; }
      const mesh = enemyMeshes.get(e);
      if (mesh) {
        if (e.dead) { if (mesh.parent) w.engine.world.remove(mesh); }
        else mesh.position.set(e.pos.x, e.stats.size * 0.8, e.pos.z);
      }
    }
    // WHY: projéteis — mover, colidir (parede/player/inimigo), dano + splash no impacto
    for (let i = w.projectiles.length - 1; i >= 0; i--) {
