      p.x += p.dir.x * p.speed * dt;
      p.z += p.dir.z * p.speed * dt;
      const tile = cellAt(w.level.grid, Math.floor(p.x), Math.floor(p.z));
      if (tile === C.TILES.WALL || tile === C.TILES.DOOR) {
        if (p.splash > 0) splashDamage(p.x, p.z, p.splash, p.damage);
        w.engine.world.remove(p.mesh);
        w.projectiles.splice(i, 1);
        continue;
      }
      if (p.owner === 'enemy') {
        const dx = p.x - w.player.pos.x;
        const dz = p.z - w.player.pos.z;
        if (dx * dx + dz * dz < 0.36) {
          w.player.damage(p.damage);
          knockback(w.player.vel, p.dir.x, p.dir.z, 2.5);
          w.engine.world.remove(p.mesh);
          w.projectiles.splice(i, 1);
          continue;
        }
      } else {
        let hit = null;
        for (const e of w.enemies) {
          if (e.dead) continue;
          const dx = p.x - e.pos.x;
          const dz = p.z - e.pos.z;
          const r = e.stats.size * 0.6;
          if (dx * dx + dz * dz < r * r) { hit = e; break; }
        }
        if (hit) {
          hit.damage(p.damage);
          if (p.splash > 0) splashDamage(p.x, p.z, p.splash, p.damage);
          w.audio.play('explosion');
          w.engine.world.remove(p.mesh);
          w.projectiles.splice(i, 1);
          continue;
        }
      }
      p.mesh.position.set(p.x, 0.35, p.z);
    }
    w.particles.update(dt);
    if (w.player.hp < lastHp) w.audio.play('damage');
    lastHp = w.player.hp;
    // WHY: condições de fim — morte (lava/inimigos) ou saída (exit)
    if (w.player.hp <= 0) { w.game.gameOver(); w.audio.play('explosion'); return; }
    const tile = cellAt(w.level.grid, Math.floor(w.player.pos.x), Math.floor(w.player.pos.z));
    if (tile === C.TILES.EXIT) { w.game.win(); w.audio.play('pickup'); }
  };

