test('combate: inimigos visíveis, tiro danifica imp, projétil inimigo fere player (W9)', async ({ page }) => {
  await boot(page);
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
  // W9: 6 imps com mesh 3D no mundo (cor 0xcc4422 de C.ENEMY.imp)
  const imps = await page.evaluate(() => {
    let n = 0;
    window.__doom.engine.scene.traverse((o) => {
      if (o.isMesh && o.material && o.material.color && o.material.color.getHex() === 0xcc4422) n++;
    });
    return n;
  });
  expect(imps).toBe(6);
  // teleporta para a borda da arena olhando +Z (yaw=PI → frente (0,1)); imps em z=40-42
  await page.evaluate(() => {
    const w = window.__doom;
    w.player.pos = { x: 17.5, z: 36.5 };
    w.player.yaw = Math.PI;
  });
  // hitscan (pistol, dano 10): 1 tiro deixa um imp com hp < 30
  await page.mouse.click(400, 300);
  await page.waitForFunction(() => window.__doom.enemies.some((e) => e.hp < 30));
  // sem atirar mais: imp ataca → projétil visível criado → chega no player → hp diminui
  await page.waitForFunction(() => window.__doom.projectiles.length > 0, null, { timeout: 3000 });
  const hp0 = await page.evaluate(() => window.__doom.player.hp);
  await page.waitForFunction((h0) => window.__doom.player.hp < h0, hp0, { timeout: 3000 });
  expect(await page.evaluate(() => window.__doom.player.hp)).toBeLessThan(hp0);
});

