test('diag combate', async ({ page }) => {
  await page.goto('/');
  await page.waitForFunction(() => window.__doom !== undefined);
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
  await page.evaluate(() => {
    const w = window.__doom;
    w.player.pos = { x: 17.5, z: 36.5 };
    w.input._yaw = Math.PI;
  });
  await page.waitForTimeout(200);
  const info = await page.evaluate(() => {
    const w = window.__doom;
    const grid = w.level.grid;
    const enemies = w.enemies.map((e) => ({ x: e.pos.x, z: e.pos.z, hp: e.hp, dead: e.dead }));
    const cells = [];
    for (let z = 36; z <= 43; z++) cells.push(`z${z}=${grid[z][17]}`);
    const dirX = Math.sin(w.player.yaw);
    const dirZ = -Math.cos(w.player.yaw);
    return {
      yaw: w.player.yaw,
      inputYaw: w.input._yaw,
      pos: w.player.pos,
      dir: { x: dirX, z: dirZ },
      cells,
      enemies,
      canFire: w.player.weapons.canFire(),
      key: w.player.weapons.key,
    };
  });
  console.log('INFO', JSON.stringify(info, null, 1));
  // tiro manual + raycast manual
