import { test } from '@playwright/test';

test('diag freeze', async ({ page }) => {
  const errors = [];
  page.on('pageerror', (e) => errors.push(`PAGEERROR: ${e.message}\n${e.stack}`));
  page.on('console', (m) => {
    if (m.type() === 'error') errors.push(`CONSOLE: ${m.text()}`);
  });
  await page.goto('/');
  await page.waitForFunction(() => window.__doom !== undefined);
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');

  // anda para frente continuamente por 8s, amostra a posição a cada 1s
  await page.keyboard.down('KeyW');
  let prev = null;
  for (let i = 0; i < 8; i++) {
    await page.waitForTimeout(1000);
    const cur = await page.evaluate(() => {
      const w = window.__doom;
      const t0 = performance.now();
      // roda 5 frames de verdade e mede o tempo — se o loop morreu, não avança
      const start = performance.now();
      let frames = 0;
      const p = w.player.pos;
      // sonda o último timestamp de frame guardado pelo engine (se existir) via rAF indireto
      return { x: p.x, z: p.z, hp: w.player.hp, state: w.game.state, now: performance.now() };
    });
    const moved = prev ? Math.abs(cur.x - prev.x) + Math.abs(cur.z - prev.z) : 0;
    console.log(`T+${i + 1}s pos=(${cur.x.toFixed(2)},${cur.z.toFixed(2)}) moved=${moved.toFixed(3)} state=${cur.state}`);
    prev = cur;
  }
  await page.keyboard.up('KeyW');
  console.log('ERRORS', JSON.stringify(errors, null, 1));
});

