import { test } from '@playwright/test';

test('diag freeze2', async ({ page }) => {
  const errors = [];
  page.on('pageerror', (e) => errors.push(`PAGEERROR: ${e.message}\n${(e.stack || '').slice(0, 600)}`));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(`CONSOLE: ${m.text().slice(0, 400)}`); });
  await page.goto('/');
  await page.waitForFunction(() => window.__doom !== undefined);
  // captura erros assíncronos
  await page.evaluate(() => {
    window.addEventListener('unhandledrejection', (e) => console.error('UNHANDLED:', e.reason && e.reason.stack || e.reason));
  });
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');

  // 1) PULA (Space) — verificar se o pulo responde
  await page.keyboard.down('Space');
  await page.waitForTimeout(400);
  const jump = await page.evaluate(() => ({ y: window.__doom.player.pos.y }));
  await page.keyboard.up('Space');

  // 2) ANDA ATÉ A ARENA (fica no range dos imps, eles atiram projéteis)
  await page.evaluate(() => {
    const w = window.__doom;
    w.player.pos = { x: 14.5, z: 39.5 };
    w.input._yaw = Math.PI / 2;
  });
  let projSeen = 0;
  for (let i = 0; i < 10; i++) {
    await page.waitForTimeout(1000);
    const cur = await page.evaluate(() => {
      const w = window.__doom;
      return { x: w.player.pos.x, z: w.player.pos.z, hp: w.player.hp, proj: w.projectiles.length, state: w.game.state };
    });
    if (cur.proj > 0) projSeen++;
    console.log(`ARENA T+${i + 1}s hp=${cur.hp} proj=${cur.proj} pos=(${cur.x.toFixed(1)},${cur.z.toFixed(1)}) state=${cur.state}`);
  }

  // 3) ATIRA repetidamente (mousedown com combate)
  for (let i = 0; i < 5; i++) {
    await page.mouse.click(400, 300);
    await page.waitForTimeout(300);
  }
  const after = await page.evaluate(() => {
    const w = window.__doom;
    return { hp: w.player.hp, state: w.game.state, proj: w.projectiles.length };
  });
  console.log('AFTER SHOOT', JSON.stringify(after));

  // 4) COLETA pickup W (teleporta para (15,2) e anda sobre ele)
  await page.evaluate(() => {
    const w = window.__doom;
    w.player.pos = { x: 15.5, z: 2.5 };
    w.input._yaw = 0;
  });
  await page.waitForTimeout(2500);
  const pickup = await page.evaluate(() => {
    const w = window.__doom;
    return { keys: w.player.weapons.inventory, key: w.player.weapons.key, state: w.game.state };
  });
  console.log('AFTER PICKUP', JSON.stringify(pickup));

  console.log('JUMP_Y', JSON.stringify(jump));
  console.log('ERRORS', JSON.stringify(errors, null, 1).slice(0, 3000));
});

