// js/world.js — construção da geometria 3D do mapa (fonte única: preview + main)
// Referências de arte: Duke Nukem 3D (texturas de tijolo/metal, viewmodels grandes),
// Quake (teto presente, materiais com rugosidade, luz direcional), Black PS2
// (iluminação dramática, olhos/emissivos brilhando no escuro), CS (silhuetas legíveis).
import * as THREE from '../vendor/three.module.js';
import C from './constants.js';

// WHY: texturas procedurais geradas 1x por canvas (sem assets externos, sem rede).
// Lazy: só no browser (buildWorld) — testes unit em node não importam este módulo.
const texCache = new Map();
const makeTexture = (name, w, h, paint) => {
  if (texCache.has(name)) return texCache.get(name);
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const g = c.getContext('2d');
  paint(g, w, h);
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  texCache.set(name, t);
  return t;
};

// WHY: ruído determinístico (semente fixa) — variação de tom sem flicker entre frames
const seededRand = (n) => {
  let s = n * 9301 + 49297;
  s = (s * 233280) % 233280;
  return s / 233280;
};

// WHY: tijolo 48×24 com argamassa escura e variação por tijolo (Duke) — repeat 1x/tile
const wallTex = () => makeTexture('wall', 128, 128, (g, w, h) => {
  g.fillStyle = '#2a1f1a';
  g.fillRect(0, 0, w, h);
  const bw = 64, bh = 32;
  for (let y = 0; y < h; y += bh) {
    const off = (y / bh) % 2 === 0 ? 0 : bw / 2;
    for (let x = -bw / 2; x < w; x += bw) {
      const v = seededRand(x * 7 + y * 13) * 26;
      const r = 112 + v, g2 = 62 + v * 0.6, b = 48 + v * 0.4;
      g.fillStyle = `rgb(${r | 0},${g2 | 0},${b | 0})`;
      g.fillRect(x + off + 2, y + 2, bw - 4, bh - 4);
    }
  }
});

// WHY: lajes de pedra 64×64 com juntas escuras e grão (Quake) — repeat 1x/tile
const floorTex = () => makeTexture('floor', 128, 128, (g, w, h) => {
  g.fillStyle = '#23232a';
  g.fillRect(0, 0, w, h);
  const s = 64;
  for (let y = 0; y < h; y += s) {
    for (let x = 0; x < w; x += s) {
      const v = seededRand(x * 3 + y * 11) * 18;
      const t = 74 + v;
      g.fillStyle = `rgb(${t | 0},${(t * 0.96) | 0},${(t * 1.05) | 0})`;
      g.fillRect(x + 2, y + 2, s - 4, s - 4);
      // grão: 8 speckles por laje
      for (let i = 0; i < 8; i++) {
        g.fillStyle = seededRand(x * 5 + y * 7 + i * 3) > 0.5 ? '#3a3a44' : '#191920';
        g.fillRect(x + 4 + seededRand(x + i * 17) * (s - 10), y + 4 + seededRand(y + i * 23) * (s - 10), 3, 3);
      }
    }
  }
});

// WHY: placas de concreto escuras no teto — fecha o mundo (Quake tem teto; sem ele o
// vazio acima das paredes quebrava a imersão)
const ceilTex = () => makeTexture('ceil', 128, 128, (g, w, h) => {
  g.fillStyle = '#1c1c22';
  g.fillRect(0, 0, w, h);
  const s = 64;
  for (let y = 0; y < h; y += s) {
    for (let x = 0; x < w; x += s) {
      const v = seededRand(x * 9 + y * 5) * 12;
      const t = 40 + v;
      g.fillStyle = `rgb(${t | 0},${(t * 0.97) | 0},${(t * 1.08) | 0})`;
      g.fillRect(x + 1, y + 1, s - 2, s - 2);
    }
  }
});

// WHY: metal com rebites para portas (Duke) — a porta é um elemento "vivo" do mapa
const doorTex = () => makeTexture('door', 128, 128, (g, w, h) => {
  g.fillStyle = '#4a3d2c';
  g.fillRect(0, 0, w, h);
  g.fillStyle = '#5c4d38';
  g.fillRect(4, 4, w - 8, h - 8);
  for (let y = 8; y < h; y += 28) {
    for (let x = 8; x < w; x += 28) {
      g.fillStyle = '#2e261a';
      g.beginPath();
      g.arc(x, y, 3.5, 0, Math.PI * 2);
      g.fill();
      g.fillStyle = '#6e5c42';
      g.beginPath();
      g.arc(x, y, 1.6, 0, Math.PI * 2);
      g.fill();
    }
  }
});

// WHY: materiais compartilhados (menos alocação por tile) — Standard com rugosidade
// (Quake) em vez de Lambert chapado; texturas procedurais (Duke) em vez de cor sólida.
export const MAT = {
  wall: new THREE.MeshStandardMaterial({ map: wallTex(), roughness: 0.92, metalness: 0.05 }),
  door: new THREE.MeshStandardMaterial({ map: doorTex(), roughness: 0.7, metalness: 0.45 }),
  lava: new THREE.MeshStandardMaterial({ color: 0xff4400, emissive: 0xcc3300, emissiveIntensity: 1.3, roughness: 0.55 }),
  floor: new THREE.MeshStandardMaterial({ map: floorTex(), roughness: 1.0, metalness: 0.0 }),
  ceil: new THREE.MeshStandardMaterial({ map: ceilTex(), roughness: 0.95, metalness: 0.0 }),
  exit: new THREE.MeshStandardMaterial({ color: 0x44ffcc, emissive: 0x22cc88, emissiveIntensity: 0.9, roughness: 0.4 }),
  secret: new THREE.MeshStandardMaterial({ color: 0xff88ff, emissive: 0x660066, emissiveIntensity: 0.6, roughness: 0.6 }),
  pickup: (color) => new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.35, roughness: 0.5 }),
};

export const PICKUP_COLORS = { H: 0x44ff44, A: 0x4488ff, W: 0xffcc00 };

// WHY: constrói a geometria estática do mapa (paredes, chão, TETO, lava, itens, tochas)
const buildWorld = (world, grid) => {
  const floorGeo = new THREE.PlaneGeometry(C.MAP.gridW, C.MAP.gridH);
  const floor = new THREE.Mesh(floorGeo, MAT.floor);
  floor.rotation.x = -Math.PI / 2;
  floor.position.set(C.MAP.gridW / 2 - 0.5, 0, C.MAP.gridH / 2 - 0.5);
  world.add(floor);

  // WHY: teto fecha o mundo (Quake) — mesmo formato do chão, a 2.2 (altura das paredes)
  const ceil = new THREE.Mesh(floorGeo, MAT.ceil);
  ceil.rotation.x = Math.PI / 2;
  ceil.position.set(C.MAP.gridW / 2 - 0.5, 2.2, C.MAP.gridH / 2 - 0.5);
  world.add(ceil);

  const wallGeo = new THREE.BoxGeometry(1, 2.2, 1);
  const doorGeo = new THREE.BoxGeometry(0.92, 2.2, 0.92);
  const lavaGeo = new THREE.BoxGeometry(0.98, 0.04, 0.98);
  // WHY: pickups com forma por tipo (model-recipes: rewarded authored forms)
  const healthGeo = buildHealthMesh();
  const armorGeo = buildArmorMesh();
  const weaponGeo = buildWeaponMesh();

  let torchCount = 0;
  for (let z = 0; z < C.MAP.gridH; z++) {
    for (let x = 0; x < C.MAP.gridW; x++) {
      const ch = grid[z][x];
      if (ch === C.TILES.WALL) {
        const m = new THREE.Mesh(wallGeo, MAT.wall);
        m.position.set(x, 1.1, z);
        world.add(m);
      } else if (ch === C.TILES.DOOR) {
        const m = new THREE.Mesh(doorGeo, MAT.door);
        m.position.set(x, 1.1, z);
        world.add(m);
      } else if (ch === C.TILES.LAVA) {
        const m = new THREE.Mesh(lavaGeo, MAT.lava);
        m.position.set(x, 0.02, z);
        world.add(m);
      } else if (ch === C.TILES.EXIT) {
        const m = new THREE.Mesh(itemGeoBase(), MAT.exit);
        m.position.set(x, 0.4, z);
        world.add(m);
      } else if (ch === C.TILES.SECRET) {
        const m = new THREE.Mesh(itemGeoBase(), MAT.secret);
        m.position.set(x, 0.4, z);
        world.add(m);
      } else if (ch === C.TILES.TORCH) {
        const light = new THREE.PointLight(C.LIGHT.torchColor, C.LIGHT.torchIntensity, C.LIGHT.torchDist);
        light.position.set(x, 1.6, z);
        world.add(light);
        torchCount++;
      } else if (ch === C.TILES.HEALTH) {
        const m = healthGeo.clone();
        m.material = MAT.pickup(PICKUP_COLORS.H);
        m.position.set(x, 0.4, z);
        world.add(m);
      } else if (ch === C.TILES.ARMOR) {
        const m = armorGeo.clone();
        m.material = MAT.pickup(PICKUP_COLORS.A);
        m.position.set(x, 0.4, z);
        world.add(m);
      } else if (ch === C.TILES.WEAPON) {
        const m = weaponGeo.clone();
        m.material = MAT.pickup(PICKUP_COLORS.W);
        m.position.set(x, 0.4, z);
        world.add(m);
      }
    }
  }
  return torchCount;
};

// WHY: geometria base dos pickups "simples" (exit/secret) — caixa pequena girando
const itemGeoBase = () => {
  const g = new THREE.Group();
  const core = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.34, 0.34));
  g.add(core);
  return g;
};

// WHY: saúde = cruz verde (forma imediatamente legível — CS/Duke: saúde é cruz)
const buildHealthMesh = () => {
  const g = new THREE.Group();
  const v = new THREE.BoxGeometry(0.1, 0.4, 0.1);
  const h = new THREE.BoxGeometry(0.3, 0.1, 0.1);
  g.add(new THREE.Mesh(v));
  g.add(new THREE.Mesh(h));
  return g;
};

// WHY: armadura = capacete azul (esfera achatada + crista) — forma de proteção
const buildArmorMesh = () => {
  const g = new THREE.Group();
  const dome = new THREE.Mesh(new THREE.SphereGeometry(0.22, 10, 8, 0, Math.PI * 2, 0, Math.PI * 0.55));
  dome.position.y = 0.06;
  const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.24, 0.05, 10));
  brim.position.y = 0.02;
  g.add(dome);
  g.add(brim);
  return g;
};

// WHY: arma = caixa com tira emissiva (munição) — forma de suprimento
const buildWeaponMesh = () => {
  const g = new THREE.Group();
  const box = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.26, 0.22));
  const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.05, 0.05));
  stripe.position.y = 0.08;
  g.add(box);
  g.add(stripe);
  return g;
};

// WHY: mesh 3D por inimigo — corpo + cabeça + chifres + olhos emissivos (Black: olhos
// brilham no escuro; Duke/Quake: silhueta caracterizada, não mais um cubo)
const buildEnemyMeshes = (world, enemies) => {
  const map = new Map();
  for (const e of enemies) {
    const s = e.stats.size;
    const mat = new THREE.MeshStandardMaterial({ color: e.stats.color, roughness: 0.85, metalness: 0.05 });
    const g = new THREE.Group();

    const body = new THREE.Mesh(new THREE.BoxGeometry(s * 0.85, s * 1.0, s * 0.7), mat);
    body.position.y = s * 0.85;
    g.add(body);

    const head = new THREE.Mesh(new THREE.BoxGeometry(s * 0.5, s * 0.42, s * 0.5), mat);
    head.position.y = s * 1.5;
    g.add(head);

    const hornGeo = new THREE.ConeGeometry(s * 0.09, s * 0.3, 6);
    const hornL = new THREE.Mesh(hornGeo, mat);
    hornL.position.set(-s * 0.14, s * 1.72, 0);
    hornL.rotation.z = -0.35;
    const hornR = hornL.clone();
    hornR.position.x = s * 0.14;
    hornR.rotation.z = 0.35;
    g.add(hornL);
    g.add(hornR);

    // WHY: olhos emissivos independentes da luz — ameaça legível no escuro (Black)
    const eyeMat = new THREE.MeshBasicMaterial({ color: 0xff4400 });
    const eyeGeo = new THREE.SphereGeometry(s * 0.06, 6, 4);
    const eyeL = new THREE.Mesh(eyeGeo, eyeMat);
    eyeL.position.set(-s * 0.12, s * 1.5, s * 0.24);
    const eyeR = eyeL.clone();
    eyeR.position.x = s * 0.12;
    g.add(eyeL);
    g.add(eyeR);

    g.position.set(e.pos.x, 0, e.pos.z);
    world.add(g);
    map.set(e, g);
  }
  return map;
};

// WHY: viewmodel FPS — grupos com partes por arma (Duke: viewmodels grandes e
// detalhados, ocupando o canto da tela); 1 visível por vez no render.
const buildViewmodel = (camera) => {
  const mk = (mat) => new THREE.MeshStandardMaterial({ color: mat, roughness: 0.6, metalness: 0.3 });

  const parts = {
    fist: (mat) => [
      { g: new THREE.BoxGeometry(0.16, 0.14, 0.20), m: mat, p: [0.32, -0.34, -0.50] },
      { g: new THREE.BoxGeometry(0.14, 0.10, 0.12), m: mat, p: [0.32, -0.22, -0.46] },
    ],
    pistol: (mat) => [
      { g: new THREE.BoxGeometry(0.07, 0.09, 0.24), m: mat, p: [0.34, -0.32, -0.62] },
      { g: new THREE.BoxGeometry(0.05, 0.05, 0.16), m: mat, p: [0.34, -0.30, -0.80] },
      { g: new THREE.BoxGeometry(0.06, 0.11, 0.09), m: mat, p: [0.33, -0.24, -0.56] },
    ],
    shotgun: (mat) => [
      { g: new THREE.BoxGeometry(0.09, 0.10, 0.30), m: mat, p: [0.34, -0.34, -0.66] },
      { g: new THREE.BoxGeometry(0.045, 0.045, 0.34), m: mat, p: [0.325, -0.33, -0.88] },
      { g: new THREE.BoxGeometry(0.045, 0.045, 0.34), m: mat, p: [0.355, -0.33, -0.88] },
      { g: new THREE.BoxGeometry(0.08, 0.10, 0.16), m: mat, p: [0.34, -0.42, -0.52] },
    ],
    rocket: (mat) => [
      { g: new THREE.BoxGeometry(0.10, 0.12, 0.30), m: mat, p: [0.34, -0.34, -0.64] },
      { g: new THREE.BoxGeometry(0.08, 0.10, 0.16), m: mat, p: [0.34, -0.34, -0.86] },
      { g: new THREE.BoxGeometry(0.06, 0.06, 0.04), m: mk(0xffaa33), p: [0.34, -0.32, -0.99] },
    ],
  };

  const map = new Map();
  for (const [key, defs] of Object.entries(parts)) {
    const mat = mk({ fist: 0x8a5a2a, pistol: 0x444455, shotgun: 0x6a4a2a, rocket: 0x4a6a3a }[key]);
    const group = new THREE.Group();
    for (const d of defs) {
      const mesh = new THREE.Mesh(d.g, d.m === mat ? mat : d.m);
      mesh.position.set(...d.p);
      group.add(mesh);
    }
    group.visible = false;
    camera.add(group);
    map.set(key, group);
  }
  return map;
};

// WHY: MeshBasicMaterial (sem luz) — projétil brilha constante, visível no escuro
const createProjectileMesh = (scene, x, z) => {
  const mesh = new THREE.Mesh(
    new THREE.SphereGeometry(0.12, 8, 6),
    new THREE.MeshBasicMaterial({ color: 0xffaa33 }),
  );
  mesh.position.set(x, 0.35, z);
  scene.add(mesh);
  return mesh;
};

export { buildWorld, buildEnemyMeshes, buildViewmodel, createProjectileMesh };

