      } else if (ch === C.TILES.SECRET) {
        const m = new THREE.Mesh(itemGeoBase(), MAT.secret);
        m.position.set(x, 0.4, z);
        world.add(m);
      } else if (ch === C.TILES.TORCH) {
        const light = new THREE.PointLight(C.LIGHT.torchColor, C.LIGHT.torchIntensity, C.LIGHT.torchDist);
        light.position.set(x, 1.6, z);
        world.add(light);
        torchCount++;
      } else if (ch === C.TILES.HEALTH) {
        const m = healthGeo.clone();
        m.material = MAT.pickup(PICKUP_COLORS.H);
        m.position.set(x, 0.4, z);
        world.add(m);
      } else if (ch === C.TILES.ARMOR) {
        const m = armorGeo.clone();
        m.material = MAT.pickup(PICKUP_COLORS.A);
        m.position.set(x, 0.4, z);
        world.add(m);
      } else if (ch === C.TILES.WEAPON) {
        const m = weaponGeo.clone();
        m.material = MAT.pickup(PICKUP_COLORS.W);
        m.position.set(x, 0.4, z);
        world.add(m);
      }
    }
  }
  return torchCount;
};

// WHY: geometria base dos pickups "simples" (exit/secret) — caixa pequena girando
const itemGeoBase = () => {
  const g = new THREE.Group();
  const core = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.34, 0.34));
  g.add(core);
  return g;
};

// WHY: saúde = cruz verde (forma imediatamente legível — CS/Duke: saúde é cruz)
const buildHealthMesh = () => {
  const g = new THREE.Group();
  const v = new THREE.BoxGeometry(0.1, 0.4, 0.1);
  const h = new THREE.BoxGeometry(0.3, 0.1, 0.1);
  g.add(new THREE.Mesh(v));
  g.add(new THREE.Mesh(h));
  return g;
};

// WHY: armadura = capacete azul (esfera achatada + crista) — forma de proteção
const buildArmorMesh = () => {
  const g = new THREE.Group();
  const dome = new THREE.Mesh(new THREE.SphereGeometry(0.22, 10, 8, 0, Math.PI * 2, 0, Math.PI * 0.55));
  dome.position.y = 0.06;
  const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.24, 0.05, 10));
  brim.position.y = 0.02;
  g.add(dome);
  g.add(brim);
  return g;
};

// WHY: arma = caixa com tira emissiva (munição) — forma de suprimento
const buildWeaponMesh = () => {
  const g = new THREE.Group();
  const box = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.26, 0.22));
  const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.05, 0.05));
  stripe.position.y = 0.08;
  g.add(box);
  g.add(stripe);
  return g;
};

// WHY: mesh 3D por inimigo — corpo + cabeça + chifres + olhos emissivos (Black: olhos
// brilham no escuro; Duke/Quake: silhueta caracterizada, não mais um cubo)
const buildEnemyMeshes = (world, enemies) => {
  const map = new Map();
  for (const e of enemies) {
    const s = e.stats.size;
    const mat = new THREE.MeshStandardMaterial({ color: e.stats.color, roughness: 0.85, metalness: 0.05 });
    const g = new THREE.Group();

    const body = new THREE.Mesh(new THREE.BoxGeometry(s * 0.85, s * 1.0, s * 0.7), mat);
    body.position.y = s * 0.85;
    g.add(body);

    const head = new THREE.Mesh(new THREE.BoxGeometry(s * 0.5, s * 0.42, s * 0.5), mat);
    head.position.y = s * 1.5;
    g.add(head);

    const hornGeo = new THREE.ConeGeometry(s * 0.09, s * 0.3, 6);
    const hornL = new THREE.Mesh(hornGeo, mat);
    hornL.position.set(-s * 0.14, s * 1.72, 0);
    hornL.rotation.z = -0.35;
    const hornR = hornL.clone();
    hornR.position.x = s * 0.14;
    hornR.rotation.z = 0.35;
    g.add(hornL);
    g.add(hornR);

    // WHY: olhos emissivos independentes da luz — ameaça legível no escuro (Black)
    const eyeMat = new THREE.MeshBasicMaterial({ color: 0xff4400 });
    const eyeGeo = new THREE.SphereGeometry(s * 0.06, 6, 4);
    const eyeL = new THREE.Mesh(eyeGeo, eyeMat);
    eyeL.position.set(-s * 0.12, s * 1.5, s * 0.24);
    const eyeR = eyeL.clone();
    eyeR.position.x = s * 0.12;
    g.add(eyeL);
    g.add(eyeR);

    g.position.set(e.pos.x, 0, e.pos.z);
    world.add(g);
    map.set(e, g);
  }
  return map;
};

// WHY: viewmodel FPS — grupos com partes por arma (Duke: viewmodels grandes e
// detalhados, ocupando o canto da tela); 1 visível por vez no render.
const buildViewmodel = (camera) => {
  const mk = (mat) => new THREE.MeshStandardMaterial({ color: mat, roughness: 0.6, metalness: 0.3 });

  const parts = {
    fist: (mat) => [
      { g: new THREE.BoxGeometry(0.16, 0.14, 0.20), m: mat, p: [0.32, -0.34, -0.50] },
      { g: new THREE.BoxGeometry(0.14, 0.10, 0.12), m: mat, p: [0.32, -0.22, -0.46] },
    ],
    pistol: (mat) => [
      { g: new THREE.BoxGeometry(0.07, 0.09, 0.24), m: mat, p: [0.34, -0.32, -0.62] },
      { g: new THREE.BoxGeometry(0.05, 0.05, 0.16), m: mat, p: [0.34, -0.30, -0.80] },
      { g: new THREE.BoxGeometry(0.06, 0.11, 0.09), m: mat, p: [0.33, -0.24, -0.56] },
    ],
    shotgun: (mat) => [
      { g: new THREE.BoxGeometry(0.09, 0.10, 0.30), m: mat, p: [0.34, -0.34, -0.66] },
      { g: new THREE.BoxGeometry(0.045, 0.045, 0.34), m: mat, p: [0.325, -0.33, -0.88] },
      { g: new THREE.BoxGeometry(0.045, 0.045, 0.34), m: mat, p: [0.355, -0.33, -0.88] },
      { g: new THREE.BoxGeometry(0.08, 0.10, 0.16), m: mat, p: [0.34, -0.42, -0.52] },
    ],
    rocket: (mat) => [
      { g: new THREE.BoxGeometry(0.10, 0.12, 0.30), m: mat, p: [0.34, -0.34, -0.64] },
      { g: new THREE.BoxGeometry(0.08, 0.10, 0.16), m: mat, p: [0.34, -0.34, -0.86] },
      { g: new THREE.BoxGeometry(0.06, 0.06, 0.04), m: mk(0xffaa33), p: [0.34, -0.32, -0.99] },
    ],
  };

  const map = new Map();
  for (const [key, defs] of Object.entries(parts)) {
    const mat = mk({ fist: 0x8a5a2a, pistol: 0x444455, shotgun: 0x6a4a2a, rocket: 0x4a6a3a }[key]);
    const group = new THREE.Group();
    for (const d of defs) {
      const mesh = new THREE.Mesh(d.g, d.m === mat ? mat : d.m);
      mesh.position.set(...d.p);
      group.add(mesh);
    }
    group.visible = false;
    camera.add(group);
    map.set(key, group);
  }
  return map;
};

// WHY: MeshBasicMaterial (sem luz) — projétil brilha constante, visível no escuro
const createProjectileMesh = (scene, x, z) => {
  const mesh = new THREE.Mesh(
    new THREE.SphereGeometry(0.12, 8, 6),
    new THREE.MeshBasicMaterial({ color: 0xffaa33 }),
  );
  mesh.position.set(x, 0.35, z);
  scene.add(mesh);
  return mesh;
};

export { buildWorld, buildEnemyMeshes, buildViewmodel, createProjectileMesh };

