// js/engine.js — Three.js scene setup (renderer, camera, fog, lights)
// Referências: Quake (tone mapping ACES + luz direcional modelando formas),
// Black PS2 (direção de luz dramática: key quente + fill frio).
import * as THREE from '../vendor/three.module.js';
import C from './constants.js';

const createEngine = (canvas) => {
  const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: false,
  });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 1.5));
  renderer.autoClear = true;
  // WHY: ACES + SRGB — range tonal cinematográfico (Quake/Black) em vez do output
  // linear chapado; emissivos saturam sem estourar branco
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.15;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(C.RENDER.background);
  scene.fog = new THREE.Fog(
    C.RENDER.background,
    C.RENDER.fogNear,
    C.RENDER.fogFar
  );

  const camera = new THREE.PerspectiveCamera(
    75,
    canvas.clientWidth / canvas.clientHeight,
    0.1,
    120
  );
  camera.position.set(0, C.PLAYER.height, 0);

  const hemi = new THREE.HemisphereLight(
    C.LIGHT.hemiSky,
    C.LIGHT.hemiGround,
    C.LIGHT.hemiIntensity
  );
  hemi.position.set(0, 50, 0);

  const ambient = new THREE.AmbientLight(C.LIGHT.ambient, 1.0);

  // WHY: key light direcional (Black) — modela as formas com um lado iluminado e
  // outro em sombra; sem sombras projetadas (caras no swiftshader)
  const key = new THREE.DirectionalLight(0xffe8c8, 0.6);
  key.position.set(24, 32, 8);

  const world = new THREE.Group();
  scene.add(hemi);
  scene.add(ambient);
  scene.add(key);
  scene.add(world);

