// Carrega o screenshot no chromium e calcula estatísticas de pixel reais
import { chromium } from 'playwright';
const b = await chromium.launch();
const p = await b.newPage();
await p.setContent('<canvas id=c></canvas>');
const stats = await p.evaluate(async (src) => {
  const img = new Image();
  img.src = 'data:image/png;base64,' + src;
  await img.decode();
  const cv = document.getElementById('c');
  cv.width = img.width; cv.height = img.height;
  const ctx = cv.getContext('2d');
  ctx.drawImage(img, 0, 0);
  const d = ctx.getImageData(0, 0, cv.width, cv.height).data;
  let sum = 0, warm = 0, dark = 0, bright = 0;
  const hist = new Array(256).fill(0);
  for (let i = 0; i < d.length; i += 4) {
    const r = d[i], g = d[i+1], bl = d[i+2];
    const lum = 0.299*r + 0.587*g + 0.114*bl;
    sum += lum; hist[Math.round(lum)]++;
    if (lum < 40) dark++;
    if (lum > 160) bright++;
    if (r > 120 && g > 60 && bl < 100) warm++;
  }
  const n = d.length / 4;
  return { w: cv.width, h: cv.height, avg: (sum/n).toFixed(1), darkPct: (100*dark/n).toFixed(1), brightPct: (100*bright/n).toFixed(1), warmPct: (100*warm/n).toFixed(1) };
}, readFileSync('/tmp/opencode/vis-check.png').toString('base64'));
console.log('PIXELSTATS', JSON.stringify(stats));
await b.close();
EOF
