// Analisa pixels da região da arma (canto inferior direito) vs resto
import { chromium } from 'playwright';
import { readFileSync } from 'fs';
const b = await chromium.launch();
const p = await b.newPage();
await p.setContent('<canvas id=c></canvas>');
const analyze = async (file) => {
  return await p.evaluate(async (src) => {
    const img = new Image();
    img.src = 'data:image/png;base64,' + src;
    await img.decode();
    const cv = document.getElementById('c');
    cv.width = img.width; cv.height = img.height;
    const ctx = cv.getContext('2d');
    ctx.drawImage(img, 0, 0);
    const W = cv.width, H = cv.height;
    const get = (x0, y0, x1, y1) => {
      const d = ctx.getImageData(x0, y0, x1 - x0, y1 - y0).data;
      let n = 0, sum = 0, nonDark = 0;
      for (let i = 0; i < d.length; i += 4) {
        const lum = 0.299*d[i] + 0.587*d[i+1] + 0.114*d[i+2];
        sum += lum; n++;
        if (lum > 60) nonDark++;
      }
      return { avg: (sum/n).toFixed(1), nonDarkPct: (100*nonDark/n).toFixed(1) };
    };
    // arma: terço inferior, metade direita (excluindo 5% borda)
    const arma = get(Math.floor(W*0.5), Math.floor(H*0.62), W - Math.floor(W*0.02), H - Math.floor(H*0.02));
    const cena = get(0, 0, W, Math.floor(H*0.6));
    return { w: W, h: H, arma, cena, global: get(0,0,W,H) };
  }, readFileSync(file).toString('base64'));
};
for (const f of ['/tmp/opencode/qual-corredor.png', '/tmp/opencode/qual-arena.png']) {
  console.log(f, JSON.stringify(await analyze(f)));
}
await b.close();
EOF
