  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
  // parede lisa na frente (sem inimigos na vista): corredor (10.5,20.5) olhando +Z
  const setup = async (slot) => {
    await page.evaluate((s) => {
      const w = window.__doom;
      w.player.pos = { x: 10.5, z: 20.5 };
      w.player.vel = { x: 0, z: 0, y: 0 };
      w.input._yaw = Math.PI;
      w.input._pitch = 0;
      w.player.weapons.switchWeapon(s);
    }, slot);
    await page.waitForTimeout(150);
    return page.screenshot();
  };
  const s1 = await setup(0); // fist (marrom 0xb07a3a)
  await page.waitForTimeout(200);
  const s2 = await setup(1); // pistol (azul 0x8899aa)
  // média da região inferior direita (arma) em cada screenshot
  const res = await page.evaluate(async ([a, b]) => {
    const avg = async (buf) => {
      const img = new Image();
      img.src = 'data:image/png;base64,' + buf;
      await img.decode();
      const cv = document.createElement('canvas');
      cv.width = img.width; cv.height = img.height;
      const ctx = cv.getContext('2d');
      ctx.drawImage(img, 0, 0);
      const W = cv.width, H = cv.height;
      const d = ctx.getImageData(Math.floor(W*0.45), Math.floor(H*0.65), Math.floor(W*0.5), Math.floor(H*0.3)).data;
      let r = 0, g = 0, bl = 0, n = 0;
      for (let i = 0; i < d.length; i += 4) { r += d[i]; g += d[i+1]; bl += d[i+2]; n++; }
      return { r: Math.round(r/n), g: Math.round(g/n), b: Math.round(bl/n) };
    };
    return { fist: await avg(a), pistol: await avg(b) };
