// WHY: ruído determinístico (semente fixa) — variação de tom sem flicker entre frames
const seededRand = (n) => {
  let s = n * 9301 + 49297;
  s = (s * 233280) % 233280;
  return s / 233280;
};

// WHY: bump map procedural (grayscale: branco = relevo alto, preto = fundo) —
// dá profundidade real às superfícies (tijolo saliente, junta funda) sem assets
const makeBump = (name, w, h, paint) => {
  const key = `bump:${name}`;
  if (texCache.has(key)) return texCache.get(key);
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const g = c.getContext('2d');
  paint(g, w, h);
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  texCache.set(key, t);
  return t;
};

// WHY: tijolo 64×32 com argamassa, sombreamento topo-base por tijolo (luz de cima)
// e variação de tom — Duke/Quake; bump: tijolo alto, junta funda
const wallTex = () => makeTexture('wall', 128, 128, (g, w, h) => {
  g.fillStyle = '#2e241c';
  g.fillRect(0, 0, w, h);
  const bw = 64, bh = 32;
  for (let y = 0; y < h; y += bh) {
    const off = (y / bh) % 2 === 0 ? 0 : bw / 2;
    for (let x = -bw / 2; x < w; x += bw) {
      const v = seededRand(x * 7 + y * 13) * 30;
      const r = 162 + v, g2 = 112 + v * 0.6, b = 78 + v * 0.4;
      // sombreamento topo→base (luz vinda de cima — forma cilíndrica do tijolo)
      const grad = g.createLinearGradient(0, y + 2, 0, y + bh - 2);
      grad.addColorStop(0, `rgb(${(r * 1.18) | 0},${(g2 * 1.15) | 0},${(b * 1.1) | 0})`);
      grad.addColorStop(0.45, `rgb(${r | 0},${g2 | 0},${b | 0})`);
      grad.addColorStop(1, `rgb(${(r * 0.62) | 0},${(g2 * 0.6) | 0},${(b * 0.58) | 0})`);
      g.fillStyle = grad;
      g.fillRect(x + off + 3, y + 3, bw - 6, bh - 6);
      // grão: speckles no tijolo
      for (let i = 0; i < 6; i++) {
        const gx = x + off + 4 + seededRand(x + i * 31) * (bw - 10);
        const gy = y + 4 + seededRand(y + i * 47) * (bh - 10);
        const sp = seededRand(gx * 13 + gy * 17);
        g.fillStyle = sp > 0.5 ? `rgba(255,235,210,${0.10 + sp * 0.1})` : `rgba(0,0,0,${0.12 + sp * 0.08})`;
        g.fillRect(gx, gy, 2, 2);
      }
    }
  }
});
