cat > check-vis2.tmp.mjs << 'EOF'
import { chromium } from 'playwright';
import { readFileSync } from 'fs';
const b = await chromium.launch();
const p = await b.newPage();
await p.setContent('<canvas id=c></canvas>');
const analyze = async (file) => await p.evaluate(async (src) => {
  const img = new Image(); img.src = 'data:image/png;base64,' + src; await img.decode();
  const cv = document.getElementById('c'); cv.width = img.width; cv.height = img.height;
  const ctx = cv.getContext('2d'); ctx.drawImage(img, 0, 0);
  const W = cv.width, H = cv.height;
  const d = ctx.getImageData(0, 0, W, H).data;
  let lumSum = 0, lumSq = 0, n = 0, dark = 0, mid = 0, bright = 0;
  for (let i = 0; i < d.length; i += 4) {
    const l = 0.299*d[i] + 0.587*d[i+1] + 0.114*d[i+2];
    lumSum += l; lumSq += l*l; n++;
    if (l < 40) dark++; else if (l < 130) mid++; else bright++;
  }
  const mean = lumSum/n;
  const std = Math.sqrt(lumSq/n - mean*mean);
  return { mean: +mean.toFixed(1), std: +std.toFixed(1), darkPct: +(100*dark/n).toFixed(1), midPct: +(100*mid/n).toFixed(1), brightPct: +(100*bright/n).toFixed(1) };
}, readFileSync(file).toString('base64'));
for (const f of ['/tmp/opencode/novo-corredor.png', '/tmp/opencode/novo-arena.png', '/tmp/opencode/qual-corredor.png']) {
  console.log(f, JSON.stringify(await analyze(f)));
}
await b.close();
EOF
cp check-vis2.tmp.mjs "check-vis2.tmp.mjs" && node check-vis2.tmp.mjs ; rm -f check-vis2.tmp.mjs

