cat > zoom-wall.tmp.mjs << 'EOF'
import { chromium } from 'playwright';
import { readFileSync } from 'fs';
const b = await chromium.launch();
const p = await b.newPage();
await p.setContent('<canvas id=c></canvas>');
// crop do centro da parede (região de tijolo) e medir micro-variação (bump)
const zoom = async (file) => await p.evaluate(async (src) => {
  const img = new Image(); img.src = 'data:image/png;base64,' + src; await img.decode();
  const cv = document.getElementById('c'); cv.width = img.width; cv.height = img.height;
  const ctx = cv.getContext('2d'); ctx.drawImage(img, 0, 0);
  // centro da tela = parede à frente (corredor olhando +Z com parede em x10 z18..)
  const d = ctx.getImageData(Math.floor(img.width*0.35), Math.floor(img.height*0.25), Math.floor(img.width*0.3), Math.floor(img.height*0.3)).data;
  let lumSum = 0, lumSq = 0, n = 0;
  for (let i = 0; i < d.length; i += 4) {
    const l = 0.299*d[i] + 0.587*d[i+1] + 0.114*d[i+2];
    lumSum += l; lumSq += l*l; n++;
  }
  const mean = lumSum/n;
  const std = Math.sqrt(Math.max(0, lumSq/n - mean*mean));
  return { wallMean: +mean.toFixed(1), wallStd: +std.toFixed(1) };
}, readFileSync(file).toString('base64'));
console.log('ANTES (qual-corredor):', JSON.stringify(await zoom('/tmp/opencode/qual-corredor.png')));
console.log('DEPOIS (novo-corredor):', JSON.stringify(await zoom('/tmp/opencode/novo-corredor.png')));
await b.close();
EOF
