  const mean = lumSum/n;
  const std = Math.sqrt(Math.max(0, lumSq/n - mean*mean));
  return { wallMean: +mean.toFixed(1), wallStd: +std.toFixed(1) };
}, readFileSync(file).toString('base64'));
