test('combate: inimigos visíveis, tiro danifica imp, projétil inimigo fere player (W9)', async ({ page }) => {
  await boot(page);
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
  // W9: 6 imps com mesh 3D no mundo — um Group por inimigo (corpo+cabeça+chifres)
  const imps = await page.evaluate(() => {
    let n = 0;
    window.__doom.engine.scene.traverse((o) => {
      if (o.isGroup && o.children.some((c) => c.isMesh && c.material && c.material.color && c.material.color.getHex() === 0xcc4422)) n++;
    });
    return n;
  });
  expect(imps).toBe(6);
  // teleporta para dentro da arena (linha 41 aberta) olhando +X (yaw=PI/2 → frente (1,0));
// imp mais próximo em (17.5, 41.5), a 3 tiles. WHY: player.update sobrescreve yaw com
// input.yaw a cada frame → setar input._yaw
  await page.evaluate(() => {
    const w = window.__doom;
    w.player.pos = { x: 14.5, z: 41.5 };
    w.input._yaw = Math.PI / 2;
  });
  // pistol (Digit2) — W9: arma inicial é fist (melee range 2.2 não alcança)
  await page.keyboard.press('Digit2');
  await page.waitForFunction(() => window.__doom.player.weapons.current === 1);
  // hitscan (pistol, dano 10): 1 tiro deixa um imp com hp < 30
  await page.mouse.click(400, 300);
  await page.waitForFunction(() => window.__doom.enemies.some((e) => e.hp < 30));
  // WHY: sem verificação de projectiles.length — imps perseguem e colam no player
  // (knockback do W9 empurra o player; imps speed 4 alcançam em ~1s), então o projétil
  // nasce colado e colide no MESMO frame (nunca visível no hook). O critério robusto é
  // o dano real: na arena (sem lava) o hp só cai por projétil/ataque inimigo.
  const hp0 = await page.evaluate(() => window.__doom.player.hp);
  await page.waitForFunction((h0) => window.__doom.player.hp < h0, hp0, { timeout: 5000 });
  expect(await page.evaluate(() => window.__doom.player.hp)).toBeLessThan(hp0);
});

test('pickups: H restaura hp, A dá armor, W dá munição (cap maxAmmo)', async ({ page }) => {
  await boot(page);
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
  await page.evaluate(() => window.__doom.player.damage(40));
