test('polish: scanline CRT ativo e loop fixed-step ~60Hz (render FPS reportado)', async ({ page }) => {
  await boot(page);
  const scan = await page.evaluate(() => getComputedStyle(document.getElementById('game'), '::after').content);
  expect(scan).not.toBe('none');
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');
  const perf = await page.evaluate(async () => {
    const w = window.__doom;
    const u0 = w.__updates ?? 0;
    let frames = 0;
    const t0 = performance.now();
    await new Promise((resolve) => {
      const tick = () => {
        frames++;
        if (performance.now() - t0 < 1000) requestAnimationFrame(tick);
        else resolve();
      };
      requestAnimationFrame(tick);
    });
    const dt = (performance.now() - t0) / 1000;
    return { updates: (w.__updates ?? 0) - u0, dt, renderFps: frames / dt };
  });
  // fixed-step: ~60 updates/s; teto folgado — swiftshader com mais geometria
  // (viewmodel + meshes W9) faz o loop acumular catch-up, updates/s pode passar de 66
  expect(perf.updates / perf.dt).toBeGreaterThan(55);
  expect(perf.updates / perf.dt).toBeLessThan(90);
  console.log(`perf: updates/s=${(perf.updates / perf.dt).toFixed(1)} renderFps=${perf.renderFps.toFixed(1)}`);
});

