// diag-anim.spec.mjs — prova programática + screenshots das animações (R37)
// Uso: npx playwright test diag-anim.spec.mjs
import { test, expect } from '@playwright/test';

test('anim: yaw/bob/queda/particulas/recoil funcionando no runtime', async ({ page }) => {
  await page.goto('/');
  await page.click('#game');
  await page.waitForFunction(() => window.__doom.game.state === 'PLAYING');

  const proof = await page.evaluate(async () => {
    const w = window.__doom;
    const out = { enemyMesh: null, death: null, particles: null, recoil: null };

    // 1) inimigo em chase vira o mesh pro player (rotation.y === yaw) + bob muda position.y
    w.player.pos.x = 17; w.player.pos.z = 39; // perto dos imps
    await new Promise((r) => setTimeout(r, 600));
    const e = w.enemies.find((x) => x.state === 'chase');
    const mesh = e ? [...w.engine.world.children].find((c) => c.type === 'Group' && c.children.some((k) => k.isMesh && k.material.color.getHex() === 0xcc4422) && Math.abs(c.position.x - e.pos.x) < 1 && Math.abs(c.position.z - e.pos.z) < 1) : null;
    if (e && mesh) {
      out.enemyMesh = {
        yaw: e.yaw.toFixed(3),
        meshYaw: mesh.rotation.y.toFixed(3),
        bobOffset: (mesh.position.y - e.stats.size * 0.8).toFixed(3),
        state: e.state,
        animT: e.animT.toFixed(1),
      };
    }

    // 2) matar um imp e provar a queda animada (rotation.x tombando, mesh ainda no mundo)
    const target = w.enemies.find((x) => x.alive);
    if (target) {
      target.damage(9999);
      await new Promise((r) => setTimeout(r, 250));
      const dying = [...w.engine.world.children].find((c) => c.type === 'Group' && c.children.some((k) => k.isMesh && k.material.color.getHex() === 0xcc4422) && Math.abs(c.position.x - target.pos.x) < 1 && Math.abs(c.position.z - target.pos.z) < 1);
      if (dying) {
        out.death = { deathT: target.deathT.toFixed(2), rotX: dying.rotation.x.toFixed(3), y: dying.position.y.toFixed(3), stillInWorld: true };
        page._deathMesh = dying; // p/ screenshot
      }
    }

    // 3) sangue: disparar hitscan no imp vizinho e contar meshes de partículas vivas
    const imp = w.enemies.find((x) => x.alive);
    if (imp) {
      imp.damage(5);
      w.particles.blood(imp.pos.x, imp.pos.z, imp.stats.size * 0.7, 8);
      await new Promise((r) => setTimeout(r, 100));
      const blood = [...w.engine.scene.children].filter((c) => c.isMesh && c.material.color.getHex() === 0xcc2222);
      out.particles = { alive: w.particles.aliveCount, meshes3D: blood.length, bloodFirst: blood[0] ? { x: blood[0].position.x.toFixed(2), y: blood[0].position.y.toFixed(2) } : null };
    }

    // 4) recoil: disparar pistola e medir viewKick + posição z do viewmodel
    const kick0 = w.viewKick ?? 0;
    w.player.weapons.key = 'pistol';
    w.player.weapons.fire(w.player, w.level.grid);
    await new Promise((r) => setTimeout(r, 50));
    out.recoil = { kickBefore: kick0, kickAfter: (w.viewKick ?? 0).toFixed(2) };

    return out;
  });

  console.log('ANIM_PROOF ' + JSON.stringify(proof));
  expect(proof.enemyMesh).not.toBeNull();
  expect(Math.abs(parseFloat(proof.enemyMesh.yaw) - parseFloat(proof.enemyMesh.meshYaw))).toBeLessThan(0.2);
  await page.screenshot({ path: '/tmp/opencode/anim-chase.png' });

  if (proof.death) {
    expect(parseFloat(proof.death.rotX)).toBeLessThan(-0.1); // tombando
    expect(proof.death.stillInWorld).toBe(true); // ainda não removeu
  }
  await page.screenshot({ path: '/tmp/opencode/anim-death.png' });

  if (proof.particles) {
    expect(proof.particles.meshes3D).toBeGreaterThan(0); // sangue visível em 3D
    await page.screenshot({ path: '/tmp/opencode/anim-blood.png' });
  }

  if (proof.recoil) {
    expect(parseFloat(proof.recoil.kickAfter)).toBeGreaterThan(0);
    await page.screenshot({ path: '/tmp/opencode/anim-recoil.png' });
  }
});

