import { PlayerEntity } from '../js/player.js';
import { WeaponSystem } from '../js/weapons.js';
import { Enemy, spawnEnemies } from '../js/enemies.js';

// WHY: input stub determinístico (browser não existe em node)
const makeInput = (over = {}) => ({
  getAxis: () => over.axis ?? { x: 0, z: 0 },
  yaw: over.yaw ?? 0,
  pitch: 0,
  isDown: () => false,
  ...over,
});

const level = buildLevel();
const weapons = new WeaponSystem();

test('R_y(+yaw): yaw=0 com wish {0,1} anda em +z', () => {
  const p = new PlayerEntity(level, makeInput({ axis: { x: 0, z: 1 }, yaw: 0 }), weapons);
  p.start();
  const z0 = p.pos.z;
  for (let i = 0; i < 30; i++) p.update(1 / 60);
  assert.ok(p.pos.z > z0, `pos.z deveria crescer (${z0} -> ${p.pos.z})`);
});

// WHY: câmera usa rotation.y = -yaw → frente = (sin yaw, -cos yaw); R_y(-yaw).
// (R_y(+yaw) era o bug "teclas WS invertidas" reportado pelo usuário)
test('R_y(-yaw): yaw=PI/2 com wish {0,1} anda em -x', () => {
  const p = new PlayerEntity(level, makeInput({ axis: { x: 0, z: 1 }, yaw: Math.PI / 2 }), weapons);
  p.start();
  const x0 = p.pos.x;
  for (let i = 0; i < 30; i++) p.update(1 / 60);
  assert.ok(p.pos.x < x0, `pos.x deveria decrescer com R_y=- (${x0} -> ${p.pos.x})`);
});

test('R_y(-yaw): yaw=-PI/2 com wish {0,1} anda em +x', () => {
  const p = new PlayerEntity(level, makeInput({ axis: { x: 0, z: 1 }, yaw: -Math.PI / 2 }), weapons);
  p.start();
  const x0 = p.pos.x;
  for (let i = 0; i < 30; i++) p.update(1 / 60);
  assert.ok(p.pos.x > x0, `pos.x deveria crescer (${x0} -> ${p.pos.x})`);
});

test('FSM uppercase: start() → "PLAYING" e pause() → "MENU" (nunca lowercase)', () => {
  const p = new PlayerEntity(level, makeInput(), weapons);
  assert.equal(p.state, 'MENU');
  p.start();
  assert.equal(p.state, 'PLAYING');
  p.pause();
  assert.equal(p.state, 'MENU');
});

test('FSM uppercase: MENU ignora input (não move mesmo com wish)', () => {
  const p = new PlayerEntity(level, makeInput({ axis: { x: 0, z: 1 }, yaw: 0 }), weapons);
  const pos = { ...p.pos };
  for (let i = 0; i < 30; i++) p.update(1 / 60);
  assert.deepEqual(p.pos, pos, 'player em MENU não deve se mover');
});

test('FSM enemy: estados lowercase consistentes (idle → chase com LOS)', () => {
  const e = new Enemy('imp', 17.5, 24.5, level.doors);
  assert.equal(e.state, 'idle');
  const player = new PlayerEntity(level, makeInput(), weapons);
  player.pos = { x: 17.5, z: 23.0 };
  e.update(1 / 60, player, level.grid);
  assert.equal(e.state, 'chase', 'imp com LOS próximo deve perseguir');
});

test('normalize map: linha curta completa para gridW e linha longa trunca', () => {
  const short = normalizeRow('abc');
  assert.equal(short.length, C.MAP.gridW);
  assert.equal(short.slice(0, 3), 'abc');
  const long = normalizeRow('#'.repeat(C.MAP.gridW + 10));
  assert.equal(long.length, C.MAP.gridW);
});
