// js/player.js — PlayerEntity (W3): FSM MENU/PLAYING, física, bob, pickups
import C from './constants.js';
import {
  applyGravity,
  applyFriction,
  accelerate,
  moveAxis,
  tryJump,
  cameraBob,
} from './move.js';

const { floor, min, max } = Math;

class PlayerEntity {
  constructor(level, input, weapons) {
    const s = level.playerSpawn;
    // WHY: centro do tile (spawn.x/z são índices inteiros do grid)
    this.pos = { x: s.x + 0.5, z: s.z + 0.5 };
    this.y = 0;
    this.vel = { x: 0, z: 0, y: 0 };
    this.yaw = s.yaw ?? -Math.PI / 2;
    this.pitch = 0;
    this.hp = C.PLAYER.startHp;
    this.armor = C.PLAYER.startArmor;
    this.onGround = true;
    this.state = 'MENU'; // FSM: MENU -> PLAYING
    this.bobTime = 0;
    this.input = input;
    this.weapons = weapons;
    this.level = level;
  }

  // WHY: FSM — transições explícitas (lição 5: compare uppercase, comente cada transição)
  start() { this.state = 'PLAYING'; }
  pause() { this.state = 'MENU'; }

  isMoving() {
    return Math.abs(this.vel.x) > 0.05 || Math.abs(this.vel.z) > 0.05;
  }

  update(dt) {
    if (this.state !== 'PLAYING') return;
    // WHY: cooldown das armas avança com o tempo de jogo (W8 — sem isso o browser
    // nunca decrementava o cooldown e canFire() ficava false após o 1º tiro)
    this.weapons.update(dt);
    const wish = this.input.getAxis();
    const yaw = this.input.yaw;

    // WHY: R_y(-yaw) — câmera usa rotation.y = -yaw, então frente = (sin yaw, -cos yaw);
    // R_y(+yaw) deixava W/S invertidos em relação à câmera (bug "teclas WS invertidas")
    const wishX = -wish.z * Math.sin(yaw) + wish.x * Math.cos(yaw);
    const wishZ = wish.z * Math.cos(yaw) + wish.x * Math.sin(yaw);

    const speed = this.input.isDown('ShiftLeft') ? C.PHYSICS.runSpeed : C.PHYSICS.walkSpeed;
    accelerate(this.vel, { x: wishX, z: wishZ }, C.PHYSICS.accel * speed, dt);
    applyFriction(this.vel, dt, this.onGround);
    if (this.input.isDown('Space')) tryJump(this.vel, this.onGround);
    applyGravity(this.vel, dt);

    // WHY: colisão horizontal por eixo — moveAxis usa pos {x,y} do grid 2D,
