// WHY: metal com rebites para portas (Duke) — a porta é um elemento "vivo" do mapa
const doorTex = () => makeTexture('door', 128, 128, (g, w, h) => {
  g.fillStyle = '#4a3d2c';
  g.fillRect(0, 0, w, h);
  g.fillStyle = '#5c4d38';
  g.fillRect(4, 4, w - 8, h - 8);
  for (let y = 8; y < h; y += 28) {
    for (let x = 8; x < w; x += 28) {
      g.fillStyle = '#2e261a';
      g.beginPath();
      g.arc(x, y, 3.5, 0, Math.PI * 2);
      g.fill();
      g.fillStyle = '#6e5c42';
      g.beginPath();
      g.arc(x, y, 1.6, 0, Math.PI * 2);
      g.fill();
    }
