});

// WHY: materiais compartilhados (menos alocação por tile) — Standard com rugosidade
// (Quake) em vez de Lambert chapado; texturas procedurais (Duke) em vez de cor sólida.
export const MAT = {
  wall: new THREE.MeshStandardMaterial({ map: wallTex(), bumpMap: wallBump(), bumpScale: 0.9, roughness: 0.92, metalness: 0.05 }),
  door: new THREE.MeshStandardMaterial({ map: doorTex(), roughness: 0.7, metalness: 0.45 }),
  lava: new THREE.MeshStandardMaterial({ color: 0xff4400, emissive: 0xcc3300, emissiveIntensity: 1.3, roughness: 0.55 }),
  floor: new THREE.MeshStandardMaterial({ map: floorTex(), bumpMap: floorBump(), bumpScale: 0.5, roughness: 1.0, metalness: 0.0 }),
  ceil: new THREE.MeshStandardMaterial({ map: ceilTex(), bumpMap: ceilBump(), bumpScale: 0.35, roughness: 0.95, metalness: 0.0 }),
  exit: new THREE.MeshStandardMaterial({ color: 0x44ffcc, emissive: 0x22cc88, emissiveIntensity: 0.9, roughness: 0.4 }),
  secret: new THREE.MeshStandardMaterial({ color: 0xff88ff, emissive: 0x660066, emissiveIntensity: 0.6, roughness: 0.6 }),
  pickup: (color) => new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.35, roughness: 0.5 }),
};

export const PICKUP_COLORS = { H: 0x44ff44, A: 0x4488ff, W: 0xffcc00 };

// WHY: constrói a geometria estática do mapa (paredes, chão, TETO, lava, itens, tochas)
const buildWorld = (world, grid) => {
  const floorGeo = new THREE.PlaneGeometry(C.MAP.gridW, C.MAP.gridH);
  const floor = new THREE.Mesh(floorGeo, MAT.floor);
  floor.rotation.x = -Math.PI / 2;
  floor.position.set(C.MAP.gridW / 2 - 0.5, 0, C.MAP.gridH / 2 - 0.5);
  world.add(floor);

  // WHY: teto fecha o mundo (Quake) — mesmo formato do chão, a 2.2 (altura das paredes)
  const ceil = new THREE.Mesh(floorGeo, MAT.ceil);
  ceil.rotation.x = Math.PI / 2;
  ceil.position.set(C.MAP.gridW / 2 - 0.5, 2.2, C.MAP.gridH / 2 - 0.5);
  world.add(ceil);

  const wallGeo = new THREE.BoxGeometry(1, 2.2, 1);
  const doorGeo = new THREE.BoxGeometry(0.92, 2.2, 0.92);
  const lavaGeo = new THREE.BoxGeometry(0.98, 0.04, 0.98);
  const itemGeo = new THREE.BoxGeometry(0.34, 0.34, 0.34);
  // WHY: pickups com forma por tipo (model-recipes: rewarded authored forms);
  // material aplicado nos filhos na construção (Group não renderiza material próprio)
  const healthGeo = buildHealthMesh(MAT.pickup(PICKUP_COLORS.H));
  const armorGeo = buildArmorMesh(MAT.pickup(PICKUP_COLORS.A));
  const weaponGeo = buildWeaponMesh(MAT.pickup(PICKUP_COLORS.W));

  let torchCount = 0;
  for (let z = 0; z < C.MAP.gridH; z++) {
    for (let x = 0; x < C.MAP.gridW; x++) {
      const ch = grid[z][x];
      if (ch === C.TILES.WALL) {
        const m = new THREE.Mesh(wallGeo, MAT.wall);
        m.position.set(x, 1.1, z);
        world.add(m);
      } else if (ch === C.TILES.DOOR) {
        const m = new THREE.Mesh(doorGeo, MAT.door);
        m.position.set(x, 1.1, z);
        world.add(m);
      } else if (ch === C.TILES.LAVA) {
        const m = new THREE.Mesh(lavaGeo, MAT.lava);
        m.position.set(x, 0.02, z);
        world.add(m);
      } else if (ch === C.TILES.EXIT) {
        const m = new THREE.Mesh(itemGeo, MAT.exit);
        m.position.set(x, 0.4, z);

    // WHY: colisão horizontal por eixo — moveAxis usa pos {x,y} do grid 2D,
    // então traduzimos para {x: col, y: row} e de volta para pos {x,z}
    const gp = { x: this.pos.x, y: this.pos.z };
    const rX = moveAxis(gp, { x: this.vel.x, y: this.vel.z }, 'x', dt, this.level.grid, C.PLAYER.radius);
    const rZ = moveAxis(rX.pos, { x: rX.vel.x, y: rX.vel.y }, 'y', dt, this.level.grid, C.PLAYER.radius);
    this.pos.x = rZ.pos.x;
    this.pos.z = rZ.pos.y;
    this.vel.x = rZ.vel.x;
    this.vel.z = rZ.vel.y;

    // WHY: altura vertical — chão em y=0, sem teto no mapa
    this.y += this.vel.y * dt;
    if (this.y <= 0) {
      this.y = 0;
      this.vel.y = 0;
      this.onGround = true;
    } else if (this.vel.y !== 0) {
      this.onGround = false;
    }

    if (this.isMoving()) this.bobTime += dt;
    this.yaw = yaw;
    this.pitch = this.input.pitch;

    this.stepHazards(dt);
    this.collectPickups();
  }

  // WHY: lava causa dano contínuo (tile LAVA do grid)
  // WHY: guard de bounds — se o player sair do grid (knockback extremo), grid[z] é
  // undefined e `undefined[x]` lançaria TypeError, matando o rAF (jogo congela)
  stepHazards(dt) {
    const row = this.level.grid[floor(this.pos.z)];
    const tile = row ? row[floor(this.pos.x)] : undefined;
    if (tile === C.TILES.LAVA) this.damage(12 * dt);
  }

  collectPickups() {
    const remaining = [];
    for (const p of this.level.pickups) {
      const d = Math.hypot(p.x + 0.5 - this.pos.x, p.z + 0.5 - this.pos.z);
      if (d < 0.6) {
        if (p.type === C.TILES.HEALTH) this.hp = min(C.PLAYER.startHp, this.hp + 25);
        else if (p.type === C.TILES.ARMOR) this.armor = min(100, this.armor + 25);
        // WHY: W9 — pickup W desbloqueia arma nova (shotgun → rocket) e SEMPRE dá
        // munição; antes só dava munição e o inventário já vinha completo (DOOM clássico)
        else if (p.type === C.TILES.WEAPON) {
          if (!this.weapons.inventory.includes('shotgun')) this.weapons.unlockWeapon('shotgun');
          else if (!this.weapons.inventory.includes('rocket')) this.weapons.unlockWeapon('rocket');
          this.weapons.addAmmo('all', 20);
        }
      } else {
        remaining.push(p);
      }
    }
    this.level.pickups = remaining;
  }

  // WHY: armadura absorve 50% do dano antes do HP (DOOM clássico)
  // WHY: sem Math.round — dano contínuo (lava 12*dt com dt<1/12) seria anulado
  damage(amount) {
    if (this.armor > 0) {
      const absorbed = min(this.armor, amount * 0.5);
      this.armor -= absorbed;
      amount -= absorbed;
    }
    this.hp = max(0, this.hp - amount);
    return this.hp;
  }

  viewY() {
    return C.PLAYER.height + cameraBob(this.bobTime, this.isMoving(), 1).y;
  }
}

export { PlayerEntity };

// js/main.js — W6: entry point (init, wire, start) — jogo completo
import C from './constants.js';
import { createEngine } from './engine.js';
import { buildLevel, cellAt } from './map.js';
import { Input } from './input.js';
import { PlayerEntity } from './player.js';
import { WeaponSystem } from './weapons.js';
import { spawnEnemies } from './enemies.js';
import { ParticleSystem } from './particles.js';
import { AudioEngine } from './audio.js';
import { buildMinimapData, renderMinimap } from './minimap.js';
import { buildHudData, renderHud } from './hud.js';
import { Game, STATES } from './game.js';
import { buildWorld, buildEnemyMeshes, buildViewmodel, createProjectileMesh, createParticleMesh } from './world.js';
import { raycastEnemy, meleeTarget } from './weapons.js';
import { knockback, cameraBob } from './move.js';

// WHY: monta o mundo do jogo (tudo que não depende do loop)
const init = () => {
  const canvas = document.getElementById('game');
  const engine = createEngine(canvas);
  engine.resize();
  const level = buildLevel();
  const input = new Input(canvas);
  const audio = new AudioEngine();
  const player = new PlayerEntity(level, input, new WeaponSystem());
  const enemies = spawnEnemies(level, 'imp', 6);
  const particles = new ParticleSystem();
  // WHY: buffers reais dos canvas overlay (hud = tela; minimap = 36×44 tiles × 6px)
  const hudCanvas = document.getElementById('hud');
  hudCanvas.width = window.innerWidth;
  hudCanvas.height = window.innerHeight;
  const mapCanvas = document.getElementById('minimap');
  mapCanvas.width = C.MAP.gridW * 6;
  mapCanvas.height = C.MAP.gridH * 6;
  const hudCtx = hudCanvas.getContext('2d');
  const mapCtx = mapCanvas.getContext('2d');
  return { engine, level, input, audio, player, enemies, particles, hudCtx, mapCtx, score: 0 };
};

