// tests/doors.test.mjs — W10: portas funcionais (KeyE abre, fechada bloqueia,
// auto-close 3s, doorway de 1 tile transitável com radius 0.4 — DBG3/DBG4)
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import C from '../js/constants.js';
import { buildLevel } from '../js/map.js';
import { PlayerEntity } from '../js/player.js';
import { WeaponSystem } from '../js/weapons.js';

// WHY: input stub determinístico (browser não existe em node); justPressed é um
// Set real para testar o consumo do KeyE pelo handleDoors
const makeInput = (over = {}) => ({
  getAxis: () => over.axis ?? { x: 0, z: 0 },
  yaw: over.yaw ?? 0,
  pitch: 0,
  isDown: () => false,
  justPressed: new Set(),
  consume: (code) => { over.justPressed?.delete?.(code); },
  ...over,
});

const level = buildLevel();
const door2610 = level.doors.find((d) => d.x === 26 && d.z === 10);
assert.ok(door2610, 'porta (26,10) deve existir no mapa');

describe('portas', () => {
  it('KeyE abre porta próxima e consome o evento', () => {
    const input = makeInput();
    const p = new PlayerEntity(level, input, new WeaponSystem());
    p.start();
    p.pos = { x: 26.5, z: 9.5 }; // hall, 1 tile ao norte da porta (26,10)
    input.justPressed.add('KeyE');
    p.update(1 / 60);
    assert.equal(door2610.state, 'open');
    assert.equal(input.justPressed.has('KeyE'), false, 'KeyE deve ser consumido');
  });

  it('porta fechada bloqueia movimento (isSolid no moveAxis)', () => {
    const input = makeInput({ axis: { x: 0, z: 1 }, yaw: 0 });
    const p = new PlayerEntity(level, input, new WeaponSystem());
    p.start();
    p.pos = { x: 26.5, z: 9.5 }; // tentando ir para o sul (porta fechada em z=10)
    for (let i = 0; i < 60; i++) p.update(1 / 60);
    assert.ok(p.pos.z < 10.0, `porta fechada deve bloquear em z<10 (chegou ${p.pos.z})`);
  });

  it('porta aberta deixa atravessar doorway de 1 tile (radius 0.4)', () => {
    const input = makeInput({ axis: { x: 0, z: 1 }, yaw: 0 });
    const p = new PlayerEntity(level, input, new WeaponSystem());
    p.start();
    p.pos = { x: 26.5, z: 9.5 };
    door2610.state = 'open';
    for (let i = 0; i < 120; i++) p.update(1 / 60);
    assert.ok(p.pos.z > 11.0, `player deve atravessar porta aberta (chegou ${p.pos.z})`);
    door2610.state = 'closed';
  });

  it('auto-close: porta abre e fecha sozinha após 3s', () => {
    const input = makeInput();
    const p = new PlayerEntity(level, input, new WeaponSystem());
    p.start();
    p.pos = { x: 26.5, z: 9.5 };
    door2610.state = 'open';
    door2610.openT = 3;
    for (let i = 0; i < 60 * 3 + 10; i++) p.update(1 / 60);
    assert.equal(door2610.state, 'closed', 'porta deve fechar sozinha após 3s');
  });

  it('KeyE fecha porta aberta imediatamente', () => {
    const input = makeInput();
    const p = new PlayerEntity(level, input, new WeaponSystem());
    p.start();
    p.pos = { x: 26.5, z: 9.5 };
    door2610.state = 'open';
    door2610.openT = 3;
    input.justPressed.add('KeyE');
    p.update(1 / 60);
    assert.equal(door2610.state, 'closed');
  });

  it('radius 0.4: doorway de 1 tile não tem "parede invisível" (DBG4)', () => {
    const p = new PlayerEntity(level, makeInput(), new WeaponSystem());
    assert.ok(C.PLAYER.radius < 0.5, 'radius deve ser < 0.5');
    // em x=c+0.5, AABB com radius 0.4 varre apenas a coluna c (doorway transitável)
    const lo = Math.floor(8.5 - C.PLAYER.radius);
    const hi = Math.floor(8.5 + C.PLAYER.radius);
    assert.equal(lo, 8);
    assert.equal(hi, 8);
  });
});

