it('isSolid custom: porta fechada bloqueia (não é WALL no grid)', () => {
      const grid = [
        ['.', 'D', '.'],
        ['.', '.', '.'],
      ];
      const doorClosed = (r, c) => grid[r] && grid[r][c] === 'D';
      const pos = { x: 0.5, y: 0.5 };
      const vel = { x: 5, y: 0 };
      // dt=1: faixa varrida vai da col 0 até col 5 (cruza a 'D' na col 1)
      const blocked = move.moveAxis(pos, vel, 'x', 1, grid, 0.4, doorClosed);
      assert.equal(blocked.collided, true);
      assert.equal(blocked.vel.x, 0);
      // sem isSolid, 'D' NÃO bloqueia (comportamento default inalterado)
      const pass = move.moveAxis(pos, vel, 'x', 1, grid, 0.4);
      assert.equal(pass.collided, false);
    });

